INSERT INTO services (id, slug, name, short_name, tagline, summary, icon, page_slug, sort_order, visible) VALUES
  (1, 'paginas-web', 'Diseño de páginas web', 'Página web', 'Un sitio propio, rápido y administrable, listo para recibir clientes desde el celular.', 'Diseñamos el sitio completo: estructura, textos guiados, formulario, botón de WhatsApp y todo lo necesario para que tu negocio se vea serio en internet. Incluye dominio, alojamiento y soporte durante el año.', 'browser', 'diseno-de-paginas-web-guatemala', 1, 1),
  (2, 'tiendas-virtuales', 'Tiendas virtuales', 'Tienda virtual', 'Vendé en línea con catálogo, carrito y cobro con tarjeta desde tu propio dominio.', 'Montamos tu tienda sobre WooCommerce, con tu catálogo cargado, opciones de envío para Guatemala y la posibilidad de cobrar con tarjeta a través de Visanet Epay. Vos administrás productos y pedidos.', 'cart', 'tiendas-virtuales-guatemala', 2, 1),
  (3, 'correo-corporativo', 'Cuentas de correo corporativo', 'Correo corporativo', 'Escribí desde tu dominio y dejá de mandar cotizaciones con una dirección de Gmail.', 'Configuramos cuentas con tu propio dominio, las dejamos funcionando en tu celular y en tu computadora, y ordenamos los registros de correo para que tus mensajes no caigan en spam.', 'mail', 'cuentas-de-correo-corporativo', 3, 1);
INSERT INTO plans (id, service_id, name, badge, price, price_text, price_strike, period, price_note, initial_payment, balance_payment, features, cta_text, cta_url, featured, sort_order, visible) VALUES
  (1, 1, 'Página web profesional', 'El más pedido', 1250, NULL, NULL, 'al año', 'Empezás con Q250 y el saldo de Q1,000 se paga al aprobar el diseño.', 250, 1000, 'Dominio .com o .gt incluido el primer año\nAlojamiento web con certificado SSL\nDiseño a la medida de tu negocio (sin plantillas recicladas)\nSecciones que necesitás: inicio, servicios, nosotros, galería y contacto\nAdaptado a celular, tablet y computadora\nFormulario de contacto que llega a tu correo\nBotón de WhatsApp en todas las páginas\nCuentas de correo con tu dominio\nCarga de tus textos y fotos por nuestro equipo\nSoporte y cambios menores durante el año', 'Cotizar mi página web', '/contacto/', 1, 1, 1),
  (2, 2, 'Tienda virtual WooCommerce', 'Precio de lanzamiento', 1750, NULL, 3600, 'al año', 'Empezás con Q350 y el saldo de Q1,400 se paga al aprobar la tienda.', 350, 1400, 'Tienda en línea sobre WooCommerce (WordPress)\nDominio y alojamiento con SSL incluidos el primer año\nCatálogo con categorías, fotos, precios y existencias\nCarrito y proceso de compra en español\nOpciones de envío por departamento y retiro en tienda\nPago contra entrega y depósito o transferencia bancaria\nPanel para que administrés productos y pedidos\nCapacitación por videollamada para tu equipo\nAdaptada a celular, que es donde compra la mayoría\nSoporte durante el año', 'Quiero mi tienda en línea', '/contacto/', 1, 1, 1),
  (3, 2, 'Cobro con tarjeta (Visanet Epay)', 'Complemento', 750, NULL, NULL, 'al año adicional', 'Se suma al plan de tienda virtual. La afiliación con Visanet y sus comisiones se contratan directamente con el banco.', NULL, NULL, 'Integración de la pasarela Visanet Epay a tu tienda\nCobro con tarjeta Visa y Mastercard en quetzales\nPruebas de compra antes de salir a producción\nAcompañamiento en el trámite de afiliación con el banco\nMantenimiento de la integración durante el año', 'Consultar cobro con tarjeta', '/contacto/', 0, 2, 1),
  (4, 3, 'Correo con tu dominio', NULL, NULL, 'Consultar', NULL, 'según cantidad de cuentas', 'El precio depende de cuántas cuentas necesitás y del espacio de cada una. Si ya tenés página con nosotros, las cuentas van incluidas en tu plan.', NULL, NULL, 'Cuentas nombre@tudominio.com\nConfiguración en celular Android y iPhone\nConfiguración en Outlook y en el correo del Mac\nAcceso por navegador (webmail) desde cualquier lugar\nRegistros SPF y DKIM para reducir el spam\nTraslado de correos si venís de otro proveedor', 'Consultar precio de correo', '/contacto/', 0, 1, 1);
