  (3, 'pagos', 'Pagos', 'Pasarelas, bancos, comisiones y facturación electrónica.', 3),
  (4, 'dominios-y-hosting', 'Dominios y hosting', 'Todo lo que hay detrás de la dirección de tu sitio.', 4),
