INSERT INTO pages (id, slug, name, h1, intro, meta_title, meta_description, canonical, robots_index, og_image, template, sort_order, visible, updated_at) VALUES
  (1, 'blog', 'Blog', 'Guías sobre sitios web y ventas en línea', 'Escribimos sobre lo que nos preguntan en las cotizaciones, con datos de Guatemala y sin relleno.', 'Blog de Páginas Web y Tiendas en Línea | Guatemala', 'Guías prácticas para negocios guatemaltecos: precios reales, cómo vender en línea, cobro con tarjeta, dominios .gt y errores al contratar diseño web.', NULL, 1, '/assets/img/og/og-blog.webp', 'blog_index', 10, 1, '2026-08-25 10:25:36'),
  (2, 'contacto', 'Contacto', 'Contacto y cotización', 'Contanos qué necesita tu negocio y te respondemos con una propuesta concreta.', 'Contacto | Cotizá tu Página Web en Guatemala', 'Escribinos por WhatsApp o dejanos tus datos y te enviamos una propuesta con precio y tiempo de entrega. Atención en línea para toda Guatemala.', NULL, 1, '/assets/img/og/og-contacto.webp', 'contact', 9, 1, '2026-08-25 10:25:36'),
  (3, 'cuentas-de-correo-corporativo', 'Correo corporativo', 'Cuentas de correo corporativo con tu dominio', 'Escribile a tus clientes desde tu dominio, no desde una dirección de Gmail.', 'Correo Corporativo con tu Dominio | Guatemala', 'Cuentas de correo con tu propio dominio para empresas de Guatemala: configuración en celular y computadora, SPF y DKIM, y traslado desde otro proveedor.', NULL, 1, '/assets/img/og/og-correo-corporativo.webp', 'service', 5, 1, '2026-08-25 10:25:36'),
  (4, 'diseno-de-paginas-web-guatemala', 'Diseño de páginas web', 'Diseño de páginas web en Guatemala', 'Sitios corporativos y de servicios diseñados desde cero, con la información ordenada como la busca tu cliente.', 'Diseño de Páginas Web en Guatemala | paginasweb.gt', 'Diseño de páginas web a la medida para empresas de Guatemala: estructura, textos, WhatsApp y panel para editar. Q1,250 al año con dominio y hosting.', NULL, 1, '/assets/img/og/og-diseno-paginas-web.webp', 'service', 2, 1, '2026-08-25 10:25:36'),
  (5, '', 'Inicio', 'Páginas Web en Guatemala', NULL, 'Páginas Web en Guatemala | Diseño desde Q1,250', 'Diseñamos páginas web y tiendas virtuales para negocios de Guatemala. Dominio, hosting y soporte incluidos desde Q1,250 al año. Empezá con Q250.', NULL, 1, '/assets/img/og/og-inicio.webp', 'home', 1, 1, '2026-08-25 10:25:36'),
  (6, 'nosotros', 'Nosotros', 'Quiénes somos', 'Somos el equipo de Servicom. paginasweb.gt es la marca con la que atendemos proyectos de sitios y tiendas.', 'Nosotros | paginasweb.gt, una marca de Servicom', 'paginasweb.gt es la marca con la que Servicom diseña sitios web en Guatemala desde 2007. Cómo trabajamos, en qué creemos y qué podés esperar de nosotros.', NULL, 1, '/assets/img/og/og-nosotros.webp', 'about', 7, 1, '2026-08-25 10:25:36'),
  (7, 'politica-de-privacidad', 'Política de privacidad', 'Política de privacidad', NULL, 'Política de Privacidad | paginasweb.gt', 'Qué datos recolectamos en este sitio, para qué los usamos, cuánto tiempo los guardamos y cómo podés pedir que los eliminemos.', NULL, 1, NULL, 'legal', 21, 1, '2026-08-25 10:25:36'),
  (8, 'portafolio', 'Portafolio', 'Portafolio de sitios web', 'Sitios reales, publicados y funcionando. Abrilos y revisá cómo se ven en tu celular.', 'Portafolio de Páginas Web en Guatemala | Trabajos', 'Sitios web que diseñamos para empresas guatemaltecas: bufetes, distribuidoras, clínicas, transporte y servicios. Todos en línea y abiertos para revisar.', NULL, 1, '/assets/img/og/og-portafolio.webp', 'portfolio', 6, 1, '2026-08-25 10:25:36'),
  (9, 'precios', 'Precios', 'Precios de páginas web en Guatemala', 'Todos los precios en quetzales, con lo que incluye cada uno y lo que se cobra aparte.', 'Precios de Páginas Web en Guatemala 2026 | Q1,250', 'Cuánto cuesta una página web en Guatemala: Q1,250 al año. Tienda virtual Q1,750. Qué incluye cada precio, cómo se paga y qué se cobra aparte.', NULL, 1, '/assets/img/og/og-precios.webp', 'pricing', 4, 1, '2026-08-25 10:25:36'),
  (10, 'preguntas-frecuentes', 'Preguntas frecuentes', 'Preguntas frecuentes sobre sitios web', 'Las dudas que más nos escriben, contestadas sin rodeos.', 'Preguntas Frecuentes sobre Páginas Web | Guatemala', 'Respuestas claras sobre dominios, hosting, tiempos de entrega, pagos, SEO y qué pasa si dejás de renovar tu página web en Guatemala.', NULL, 1, '/assets/img/og/og-preguntas-frecuentes.webp', 'faq', 8, 1, '2026-08-25 10:25:36'),
  (11, 'terminos-y-condiciones', 'Términos y condiciones', 'Términos y condiciones del servicio', NULL, 'Términos y Condiciones | paginasweb.gt', 'Condiciones del servicio: suscripción anual, renovación, dominio, pagos, alcance del soporte y jurisdicción en Guatemala.', NULL, 1, NULL, 'legal', 20, 1, '2026-08-25 10:25:36'),
  (12, 'tiendas-virtuales-guatemala', 'Tiendas virtuales', 'Tiendas virtuales en Guatemala', 'Vendé desde tu propio dominio, con carrito, envíos por departamento y cobro con tarjeta.', 'Tiendas Virtuales en Guatemala | WooCommerce y tarjeta', 'Tiendas en línea con WooCommerce para Guatemala: catálogo, envíos, cobro con tarjeta por Visanet Epay y panel propio. Q1,750 al año, antes Q3,600.', NULL, 1, '/assets/img/og/og-tiendas-virtuales.webp', 'service', 3, 1, '2026-08-25 10:25:36');
INSERT INTO page_sections (id, page_id, block_type, eyebrow, heading, subheading, body, image, image_alt, cta_text, cta_url, extra, sort_order, visible) VALUES
  (1, 1, 'page_hero', 'Blog', 'Guías sobre sitios web y ventas en línea', 'Publicamos poco y con calma. Cada guía nace de una pregunta que nos hicieron varios clientes, y la escribimos con precios, plataformas y trámites que aplican en Guatemala, no con ejemplos de otro país.', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (2, 1, 'rich_text', NULL, 'Cómo elegimos de qué escribir', NULL, '<p>Cada guía nace de una conversación real con un cliente. Cuando la misma duda aparece tres o cuatro veces en cotizaciones distintas, sabemos que vale la pena responderla bien y dejarla escrita.</p>\n<p>Por eso publicamos poco. No tenemos un calendario que nos obligue a sacar cuatro artículos al mes para alimentar un algoritmo, y no vamos a llenar esta sección de textos genéricos que se podrían haber escrito en cualquier país. Si un tema no lo dominamos, no lo tocamos; y cuando algo cambia —un precio del mercado, una condición de un banco, una regla de la SAT— volvemos sobre el artículo y lo actualizamos en lugar de publicar uno nuevo casi igual.</p>\n<p>Lo que sí vas a encontrar acá: montos en quetzales, plataformas que de verdad operan en el país, trámites tal como se hacen localmente y advertencias sobre lo que hemos visto salir mal. Y cuando la respuesta honesta a una pregunta es «no te conviene contratarlo», eso también lo escribimos, aunque vaya en contra de vendernos.</p>\n<p>Tampoco encontrarás listas de «los 20 mejores complementos» ni resúmenes de noticias que ya leíste en otro lado. Ese tipo de contenido se produce en volumen porque es fácil, no porque le sirva a alguien. Nuestro criterio para publicar es sencillo: si un dueño de negocio puede tomar una mejor decisión después de leer el texto, vale la pena; si solo va a quedarse con la sensación de haber leído algo, no.</p>\n<p>Si tenés una pregunta que no está resuelta en ninguna de estas guías, escribinos. Contestamos por WhatsApp aunque no seas cliente, y si la duda se repite lo suficiente, termina convertida en el siguiente artículo. Buena parte de lo que está publicado acá empezó exactamente así, en una conversación de cotización que se alargó porque valía la pena explicarlo bien.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (3, 1, 'features', 'Índice', 'Qué vas a encontrar en cada guía', NULL, NULL, NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"chart\",\"title\":\"Precios del mercado\",\"text\":\"Los rangos que se manejan hoy, qué justifica cada salto de precio y las preguntas que hay que hacer antes de aceptar una cotización.\"},{\"icon\":\"cart\",\"title\":\"Vender en línea\",\"text\":\"Desde decidir si tu negocio está listo hasta configurar envíos, formas de pago y la emisión de comprobantes.\"},{\"icon\":\"card\",\"title\":\"Cobros con tarjeta\",\"text\":\"Cómo funciona la afiliación bancaria, qué comisiones esperar y por qué a veces conviene esperar antes de activarla.\"},{\"icon\":\"search\",\"title\":\"Dominios y hosting\",\"text\":\"Qué extensión conviene, a nombre de quién debe quedar registrada y qué pasa el día que decidís cambiar de proveedor.\"},{\"icon\":\"shield\",\"title\":\"Antes de contratar\",\"text\":\"Las cláusulas y omisiones que salen caras después, con una lista de verificación de nueve puntos para revisar cualquier propuesta.\"},{\"icon\":\"edit\",\"title\":\"Decisiones de plataforma\",\"text\":\"Comparaciones con números a tres años, no con opiniones: qué te conviene según cómo vendés y quién va a administrar el sitio.\"}]}', 3, 1),
  (4, 2, 'page_hero', 'Hablemos', 'Contacto y cotización', 'La forma más rápida es WhatsApp. Si preferís dejar todo por escrito, el formulario nos da la información completa desde el inicio y te respondemos con una propuesta, no con un \"gracias por escribir\".', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (5, 2, 'contact_form', NULL, 'Pedí tu cotización', 'Mientras más nos contés, más concreta será la respuesta.', NULL, NULL, NULL, NULL, NULL, NULL, 2, 1),
  (6, 2, 'rich_text', NULL, 'Qué nos ayuda a darte una respuesta concreta', NULL, '<p>No hace falta que tengás todo resuelto para escribirnos. Pero si podés adelantarnos estas cuatro cosas, la propuesta que te mandemos va a ser mucho más precisa y nos ahorramos dos o tres idas y venidas:</p>\n<ul>\n  <li><strong>A qué se dedica tu negocio y a quién le vende.</strong> No el rubro general, sino lo concreto: si vendés equipo industrial, a qué tipo de empresa; si sos despacho, en qué áreas trabajás de verdad.</li>\n  <li><strong>Qué te preguntan siempre tus clientes.</strong> Abrí tu WhatsApp y contanos las cinco preguntas que más repetís. De ahí sale la estructura del sitio.</li>\n  <li><strong>Qué material ya tenés.</strong> Logotipo en buena calidad, fotografías propias, listado de servicios o productos, textos que ya usás en presentaciones. Si no tenés nada, también está bien: te decimos qué conseguir.</li>\n  <li><strong>Si ya tenés dominio o sitio.</strong> Si tu página actual ya tiene visitas, conviene migrarla con cuidado para no perder el posicionamiento acumulado.</li>\n</ul>\n<p>Y si lo que tenés es una cotización de otro proveedor y querés una segunda opinión, mandanosla. La revisamos y te decimos si el precio es razonable para lo que ofrece, aunque después contratés con ellos. Preferimos eso a que alguien pague de más por algo que no le va a servir.</p>', NULL, NULL, NULL, NULL, NULL, 3, 1),
  (7, 2, 'rich_text', NULL, 'Lo que no hacemos', NULL, '<p>Para ahorrarte tiempo: no desarrollamos aplicaciones móviles, no hacemos sistemas contables ni de inventario a la medida, no gestionamos campañas de publicidad pagada y no manejamos redes sociales. Nos dedicamos a sitios web, tiendas en línea y correo corporativo, y preferimos hacer bien eso a estirarnos hacia servicios donde no somos los mejores.</p>\n<p>Si tu proyecto necesita algo de esa lista, decinos igual: casi siempre podemos orientarte sobre qué buscar y qué preguntas hacerle a quien lo vaya a hacer.</p>', NULL, NULL, NULL, NULL, NULL, 4, 1),
  (8, 2, 'rich_text', NULL, 'Qué pasa después de que nos escribís', NULL, '<p>Primero leemos con calma lo que nos mandaste y, si hace falta, te hacemos dos o tres preguntas para entender bien el negocio. Después te enviamos una propuesta con tres cosas claras: qué secciones tendría tu sitio, cuánto cuesta y en cuánto tiempo lo entregamos. Si nos escribís por la tarde, lo normal es que tengas respuesta al día siguiente hábil.</p>\n<p>No hacemos seguimiento insistente. Si te interesa, seguimos; si no, ahí queda y podés escribirnos cuando quieras. Y si nos preguntás por algo que no hacemos —una aplicación móvil, un sistema contable, publicidad pagada— te lo decimos de una vez en lugar de estirar la conversación.</p>', NULL, NULL, NULL, NULL, NULL, 5, 1),
  (9, 3, 'page_hero', 'Servicio', 'Cuentas de correo corporativo con tu dominio', 'Creamos las cuentas con tu propio dominio, las dejamos configuradas en tu celular y en tu computadora, y ordenamos los registros técnicos para que tus mensajes lleguen a la bandeja de entrada y no a la carpeta de spam.', NULL, '/assets/img/servicio-correo-corporativo.svg', 'Ilustración de bandeja de correo con dominio propio', 'Consultar precio', 'whatsapp', NULL, 1, 1),
  (10, 3, 'rich_text', NULL, 'Por qué importa más de lo que parece', NULL, '<p>Mandar una cotización de Q40,000 desde una dirección de Gmail con números al final le baja la credibilidad al negocio antes de que el cliente lea el precio. Es injusto, pero pasa. En procesos de compra corporativos, más de una empresa descarta proveedores que no escriben desde su propio dominio, y en instituciones públicas a veces ni siquiera aceptan correos de dominios gratuitos.</p>\n<p>Además hay una razón práctica: cuando un colaborador se va, la cuenta corporativa la controlás vos. Con una cuenta personal, se lleva el historial de conversaciones con tus clientes. Hemos visto negocios perder toda la relación con una cuenta grande porque el vendedor manejaba todo desde su correo personal.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (11, 3, 'features', 'Qué incluye', 'El servicio completo', NULL, NULL, NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"mail\",\"title\":\"Cuentas con tu dominio\",\"text\":\"Creamos las direcciones que necesités: personales, de área (ventas, info, cobros) y alias que reenvían a otra cuenta.\"},{\"icon\":\"phone\",\"title\":\"Configuración en tus dispositivos\",\"text\":\"Dejamos el correo andando en Android, iPhone, Outlook y el correo de Mac. Con una videollamada resolvemos toda la empresa.\"},{\"icon\":\"shield\",\"title\":\"SPF, DKIM y DMARC\",\"text\":\"Los registros que le dicen a Gmail y Outlook que tus correos son legítimos. Sin esto, tus mensajes acaban en spam sin que sepas por qué.\"},{\"icon\":\"box\",\"title\":\"Traslado desde tu proveedor actual\",\"text\":\"Si ya tenés correo en otro lado, migramos las cuentas y el historial cuando la plataforma lo permite, con la menor interrupción posible.\"},{\"icon\":\"browser\",\"title\":\"Acceso por navegador\",\"text\":\"Webmail desde cualquier computadora, útil cuando estás fuera de la oficina o se dañó el equipo.\"},{\"icon\":\"edit\",\"title\":\"Buenas prácticas\",\"text\":\"Te dejamos firmas uniformes para todo el equipo y recomendaciones de respaldo y contraseñas.\"}]}', 3, 1),
  (12, 3, 'pricing_service', 'Inversión', 'Precio del correo corporativo', 'El precio depende de cuántas cuentas necesitás y del espacio de cada una. Si contratás una página web con nosotros, las cuentas van incluidas.', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1),
  (13, 3, 'rich_text', NULL, 'Correo propio o Google Workspace', NULL, '<p>Hay dos caminos y los dos son válidos. El correo en tu propio alojamiento es más económico y suficiente para un equipo pequeño que manda y recibe correo normal. Google Workspace o Microsoft 365 cuestan una mensualidad por usuario, pero traen Drive, calendarios compartidos, documentos colaborativos y un filtro de spam mejor.</p>\n<p>Nuestra recomendación honesta: si son menos de cinco personas y solo necesitan correo, el alojamiento propio está bien. Si ya comparten archivos, agendan reuniones y trabajan documentos entre varios, conviene pagar la plataforma. Podemos configurar cualquiera de las dos, incluida la parte de DNS que casi siempre es donde se traba la gente.</p>', NULL, NULL, NULL, NULL, NULL, 5, 1),
  (14, 3, 'faq', 'Preguntas', 'Dudas sobre correo corporativo', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, 1),
  (15, 3, 'cta', NULL, '¿Cuántas cuentas necesita tu empresa?', 'Contanos cuántas personas van a usar correo y te pasamos el precio.', NULL, NULL, NULL, 'Consultar por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Escribir por formulario\",\"cta2_url\":\"/contacto/\"}', 7, 1),
  (16, 4, 'page_hero', 'Servicio', 'Diseño de páginas web en Guatemala', 'Diseñamos el sitio completo: estructura, redacción, imágenes y configuración técnica. Vos aportás la información de tu negocio; nosotros lo convertimos en una página que un cliente entiende en treinta segundos.', NULL, '/assets/img/servicio-paginas-web.svg', 'Ilustración de una página web con secciones ordenadas', 'Cotizar mi página', 'whatsapp', '{\"cta2_text\":\"Ver precios\",\"cta2_url\":\"/precios/\"}', 1, 1),
  (17, 4, 'rich_text', NULL, 'Para quién es este servicio', NULL, '<p>Este servicio es para el negocio que ya tiene clientes y necesita presentarse en serio: la distribuidora que quiere mandar su catálogo a una empresa grande, el bufete que compite con otros cinco por el mismo caso, el taller que atiende por WhatsApp y ya no da abasto contestando lo mismo, la clínica que necesita que la encuentren cuando alguien busca su especialidad en Google.</p>\n<p>No es para quien busca \"algo bonito\" sin saber qué quiere lograr. Si todavía no tenés claro a quién le vendés ni qué te diferencia, la primera conversación se la dedicamos a eso. Un sitio bien diseñado sobre un mensaje confuso sigue siendo un sitio confuso.</p>\n<p>Trabajamos con empresas de Guatemala y con guatemaltecos que operan desde afuera. Todo el proceso es en línea: llamadas, videollamadas, WhatsApp y correo. No cobramos visitas ni hacemos perder medio día en tráfico para una reunión que se resuelve en veinte minutos de llamada.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (18, 4, 'features', 'Qué incluye', 'Todo lo que entra en el diseño de tu sitio', NULL, NULL, NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"layout\",\"title\":\"Estructura a la medida\",\"text\":\"Definimos qué secciones necesita tu negocio. Una importadora no necesita lo mismo que una clínica, y forzar la misma plantilla para todo es lo que hace que los sitios se sientan genéricos.\"},{\"icon\":\"edit\",\"title\":\"Redacción de los textos\",\"text\":\"Nosotros escribimos. Vos revisás y corregís lo que solo vos sabés: nombres técnicos, garantías, cobertura, condiciones. Es la parte que más atrasa los proyectos cuando el cliente tiene que redactar solo.\"},{\"icon\":\"image\",\"title\":\"Preparación de imágenes\",\"text\":\"Recortamos, comprimimos y ordenamos tus fotos. Si tenés material del que no estás seguro, te decimos qué sirve y qué conviene volver a tomar con el celular.\"},{\"icon\":\"phone\",\"title\":\"Versión móvil real\",\"text\":\"Probamos el sitio en pantallas de 360, 390, 768, 1024 y 1440 píxeles. No es \\\"que se vea\\\", es que se use cómodo con una sola mano.\"},{\"icon\":\"search\",\"title\":\"SEO de base\",\"text\":\"Título y descripción únicos por página, direcciones legibles, encabezados con jerarquía, mapa del sitio, datos estructurados y velocidad de carga cuidada.\"},{\"icon\":\"shield\",\"title\":\"Dominio, hosting y SSL\",\"text\":\"Registramos el dominio a nombre de tu empresa, configuramos el alojamiento y dejamos el certificado activo. El primer año va incluido en el precio.\"},{\"icon\":\"mail\",\"title\":\"Correos con tu dominio\",\"text\":\"Creamos las cuentas y las configuramos en tu celular y computadora. Dejar de escribir desde una dirección de Gmail cambia cómo te percibe un cliente corporativo.\"},{\"icon\":\"chart\",\"title\":\"Analítica configurada\",\"text\":\"Instalamos Google Analytics y Search Console para que sepas cuánta gente entra, desde dónde y qué páginas mira.\"}]}', 3, 1),
  (19, 4, 'rich_text', NULL, 'Cómo decidimos las secciones de tu sitio', NULL, '<p>La estructura no sale de una plantilla, sale de tus preguntas frecuentes. Antes de diseñar te pedimos algo concreto: abrí tu WhatsApp de negocio y contanos las cinco cosas que más te preguntan. Casi siempre son estas: cuánto cuesta, si cubren mi zona, cuánto tardan, si dan factura y si tienen experiencia en algo parecido a lo mío.</p>\n<p>Cada una de esas preguntas se convierte en una sección o en una respuesta dentro de una sección. Así el sitio deja de ser un folleto y empieza a trabajar. Un sitio corporativo típico termina con inicio, servicios (con una página por servicio importante), nosotros, portafolio o casos, preguntas frecuentes y contacto. Pero si tu negocio vive de cotizaciones por volumen, quizá lo más importante sea un formulario bien pensado; y si vivís de emergencias, lo más importante es que el número esté visible sin hacer scroll.</p>\n<p>Una regla que aplicamos siempre: una página, una intención. No creamos veinte páginas casi iguales cambiando el nombre del municipio para intentar aparecer en más búsquedas. Eso Google lo detecta como páginas puerta y termina hundiendo todo el dominio. Preferimos menos páginas, cada una con contenido que se sostiene solo.</p>', NULL, NULL, NULL, NULL, NULL, 4, 1),
  (20, 4, 'process', 'Tiempos', 'Cuánto tarda y de qué depende', 'El diseño no es lo que atrasa un proyecto. Lo que atrasa es esperar el contenido.', NULL, NULL, NULL, NULL, NULL, '{\"steps\":[{\"title\":\"Semana 1 · Información y estructura\",\"text\":\"Recopilamos logo, fotos, listado de servicios y datos de contacto. Te mandamos el esquema de secciones para aprobación.\"},{\"title\":\"Semana 2 · Diseño y redacción\",\"text\":\"Armamos el sitio en una dirección de prueba con los textos ya escritos, para que revises sobre algo real y no sobre una imagen.\"},{\"title\":\"Semana 3 · Ajustes\",\"text\":\"Aplicamos tus correcciones. Aquí es donde algunos proyectos se detienen: si el material tarda en llegar, la fecha se corre.\"},{\"title\":\"Publicación\",\"text\":\"Apuntamos el dominio, activamos SSL, configuramos correos y analítica, y te capacitamos en el panel.\"}]}', 5, 1),
  (21, 4, 'pricing_service', 'Inversión', 'Precio del diseño de página web', 'Un solo plan, precio anual, sin costos ocultos.', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1),
  (22, 4, 'rich_text', NULL, 'Qué pasa después del primer año', NULL, '<p>El servicio funciona como una suscripción anual. La renovación mantiene tu dominio activo, el alojamiento con SSL, los respaldos, las cuentas de correo y el soporte para cambios menores. Si en algún momento decidís no renovar, el dominio es tuyo: te entregamos los accesos y los archivos para que lo lleves a donde quieras. No amarramos clientes con el dominio, porque un cliente que se queda por obligación no recomienda a nadie.</p>\n<p>Los cambios menores (actualizar un precio, cambiar una foto, corregir un texto, agregar un servicio a la lista) están incluidos, y además podés hacerlos vos desde el panel. Los rediseños completos o funciones nuevas, como agregar una tienda, un sistema de citas o una integración con otro sistema, se cotizan aparte.</p>', NULL, NULL, NULL, NULL, NULL, 7, 1),
  (23, 4, 'related_links', NULL, 'Seguí leyendo', NULL, NULL, NULL, NULL, NULL, NULL, '{\"links\":[{\"url\":\"/precios/\",\"title\":\"Precios de los tres servicios\",\"text\":\"Tabla comparativa de página web, tienda virtual y correo corporativo.\"},{\"url\":\"/tiendas-virtuales-guatemala/\",\"title\":\"¿Necesitás vender en línea?\",\"text\":\"Si vas a cobrar por el sitio, el servicio que te sirve es la tienda virtual.\"},{\"url\":\"/blog/errores-al-contratar-diseno-web-guatemala/\",\"title\":\"7 errores al contratar diseño web\",\"text\":\"Lo que revisamos nosotros cuando nos toca rescatar un sitio mal hecho.\"},{\"url\":\"/portafolio/\",\"title\":\"Portafolio\",\"text\":\"24 sitios en línea que podés abrir y revisar ahora mismo.\"}]}', 8, 1),
  (24, 4, 'faq', 'Preguntas', 'Dudas sobre el diseño de páginas web', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, 1),
  (25, 4, 'cta', NULL, 'Contanos de tu negocio y te decimos qué sitio necesita', 'Sin compromiso. Si el proyecto no amerita la inversión, te lo decimos de una vez.', NULL, NULL, NULL, 'Escribir por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Llenar formulario\",\"cta2_url\":\"/contacto/\"}', 10, 1);
INSERT INTO page_sections (id, page_id, block_type, eyebrow, heading, subheading, body, image, image_alt, cta_text, cta_url, extra, sort_order, visible) VALUES
  (26, 5, 'hero', 'Una marca de Servicom · desde 2007', 'Páginas Web en Guatemala', 'Diseñamos el sitio que tu negocio necesita para dejar de explicar lo mismo por mensaje: qué vendés, por qué valés lo que cobrás y cómo te contactan. Con dominio, alojamiento y soporte incluidos, desde Q1,250 al año.', NULL, '/assets/img/hero-sitio-en-celular-y-laptop.webp', 'Sitio web guatemalteco mostrado en una laptop y en un celular', 'Cotizar por WhatsApp', 'whatsapp', '{\"accent\":\"que sí traen clientes\",\"cta2_text\":\"Ver precios\",\"cta2_url\":\"/precios/\",\"notes\":[\"Respuesta el mismo día hábil\",\"Trabajamos 100% en línea\",\"Precios en quetzales, sin sorpresas\"]}', 1, 1),
  (27, 5, 'stats', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"items\":[{\"value\":\"18\",\"label\":\"años diseñando sitios en Guatemala\"},{\"value\":\"24\",\"label\":\"sitios publicados que podés visitar hoy\"},{\"value\":\"Q250\",\"label\":\"para arrancar tu proyecto\"},{\"value\":\"100%\",\"label\":\"del trabajo en línea, sin visitas presenciales\"}]}', 2, 1),
  (28, 5, 'rich_text', 'Por qué existe este sitio', 'Un sitio web sirve cuando le quita trabajo a tu negocio', NULL, '<p>La mayoría de negocios guatemaltecos ya tiene página de Facebook, catálogo en WhatsApp y quizá un perfil en Instagram. Y aun así pierden clientes todos los días por lo mismo: alguien pregunta el precio a las nueve de la noche, nadie contesta hasta el día siguiente, y para entonces ya compró en otro lado. O el cliente pide \"algo formal para presentarlo a la empresa\" y lo único que hay para mandar es una foto de un catálogo.</p>\n<p>Una página web bien hecha resuelve eso sin que vos tengás que estar pegado al celular. Contesta las preguntas de siempre, muestra tu trabajo con orden, deja claro cuánto cuesta o por qué hay que cotizar, y te llega el contacto ya con la información que necesitás para responder. No reemplaza a tu vendedor: le quita de encima las cinco preguntas que repite todo el día.</p>\n<p>Nosotros llevamos desde 2007 haciendo exactamente eso para empresas de Guatemala: bufetes, talleres, distribuidoras, clínicas, importadoras y negocios de servicio a domicilio. Aprendimos que lo que funciona aquí no es el sitio más elaborado, sino el que carga rápido con datos móviles, se entiende en una pantalla de seis pulgadas y tiene el botón de WhatsApp donde la persona lo va a buscar.</p>', NULL, NULL, NULL, NULL, NULL, 3, 1),
  (29, 5, 'services_grid', 'Qué hacemos', 'Tres servicios, sin paquetes confusos', 'No vendemos veinte planes con nombres de metales. Hacemos tres cosas y las hacemos completas.', NULL, NULL, NULL, NULL, NULL, NULL, 4, 1),
  (30, 5, 'features', 'Cómo trabajamos', 'Lo que incluye cualquier proyecto, sin costo extra', NULL, '<p>Estas cosas no son \"el plan premium\". Van incluidas porque un sitio sin ellas no sirve, y cobrarlas aparte sería vender a medias.</p>', NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"phone\",\"title\":\"Diseño pensado desde el celular\",\"text\":\"Más de siete de cada diez visitas en Guatemala llegan desde un teléfono. Empezamos el diseño ahí y después lo ampliamos a computadora, no al revés.\"},{\"icon\":\"bolt\",\"title\":\"Carga rápida con datos móviles\",\"text\":\"Optimizamos imágenes y código para que el sitio abra aunque la señal esté floja. Un segundo de más es un cliente menos.\"},{\"icon\":\"shield\",\"title\":\"Certificado SSL y respaldos\",\"text\":\"Tu sitio abre con candado en el navegador desde el primer día, y guardamos respaldos periódicos del alojamiento.\"},{\"icon\":\"search\",\"title\":\"Bases de SEO bien puestas\",\"text\":\"Títulos, descripciones, direcciones limpias, mapa del sitio y datos estructurados. Sin promesas de \\\"primer lugar en una semana\\\".\"},{\"icon\":\"chat\",\"title\":\"WhatsApp integrado de verdad\",\"text\":\"Botón flotante con mensaje prellenado, para que el cliente escriba sin tener que explicar de dónde salió.\"},{\"icon\":\"edit\",\"title\":\"Vos podés editar tu contenido\",\"text\":\"Te dejamos un panel en español para cambiar textos, precios, fotos y publicaciones sin depender de nosotros.\"}]}', 5, 1),
  (31, 5, 'process', 'El proceso', 'De la primera llamada al sitio publicado', 'Cinco pasos, sin reuniones eternas. Todo se puede hacer por WhatsApp, correo y videollamada.', NULL, NULL, NULL, NULL, NULL, '{\"steps\":[{\"title\":\"Conversamos qué necesita tu negocio\",\"text\":\"Una llamada o un chat de veinte minutos: a qué te dedicás, quién te compra, qué te preguntan siempre y qué querés lograr con el sitio.\"},{\"title\":\"Definimos estructura y presupuesto\",\"text\":\"Te decimos qué secciones tiene sentido incluir y cuánto cuesta. Si el proyecto no amerita el gasto, te lo decimos.\"},{\"title\":\"Diseñamos y armamos el contenido\",\"text\":\"Con Q250 arrancamos. Nosotros redactamos y ordenamos la información; vos nos pasás fotos, logo y los datos que solo vos sabés.\"},{\"title\":\"Revisás y pedís cambios\",\"text\":\"Te mostramos el sitio funcionando en una dirección de prueba. Ajustamos textos, colores y orden de las secciones hasta que estés conforme.\"},{\"title\":\"Publicamos y te enseñamos a usarlo\",\"text\":\"Configuramos dominio, SSL, correos y analítica. Te damos acceso al panel y una capacitación por videollamada.\"}]}', 6, 1),
  (32, 5, 'portfolio_grid', 'Portafolio', 'Sitios que están en línea ahora mismo', 'No son maquetas de presentación: son sitios de clientes reales que podés abrir y revisar.', NULL, NULL, NULL, 'Ver todo el portafolio', '/portafolio/', '{\"limit\":8}', 7, 1),
  (33, 5, 'pricing_summary', 'Precios', 'Cuánto cuesta, en quetzales y sin letra chiquita', 'Precio anual que incluye dominio, alojamiento y soporte. Empezás con un pago inicial y el saldo se paga cuando aprobás el diseño.', NULL, NULL, NULL, 'Ver el detalle de precios', '/precios/', NULL, 8, 1),
  (34, 5, 'comparison', 'Para que decidas con criterio', 'Cómo trabajamos y cómo no', 'No hablamos de otras agencias. Solo dejamos claro qué esperar de nosotros para que compares con lo que te ofrezcan.', NULL, NULL, NULL, NULL, NULL, '{\"yes_title\":\"Lo que sí hacemos\",\"no_title\":\"Lo que no vas a encontrar acá\",\"yes\":[\"Precio cerrado en quetzales antes de empezar\",\"Dominio a nombre de tu empresa, no del nuestro\",\"Panel propio para que edités sin pedirnos permiso\",\"Textos redactados por nosotros con la información que nos das\",\"Soporte con una persona que conoce tu proyecto\",\"Entrega de accesos completos cuando los pedís\"],\"no\":[\"Promesas de aparecer primero en Google en una semana\",\"Plantillas compradas que ya usaron otros diez negocios\",\"Cobros sorpresa por cambiar un texto o una foto\",\"Contratos que te amarran el dominio\",\"Sitios pesados llenos de animaciones que nadie ve\",\"Reseñas o cifras inventadas para verse más grandes\"]}', 9, 1),
  (35, 5, 'testimonials', 'Clientes', 'Lo que dicen quienes ya trabajaron con nosotros', 'Publicamos únicamente testimonios verificables de clientes reales.', NULL, NULL, NULL, NULL, NULL, NULL, 10, 1),
  (36, 5, 'posts_grid', 'Blog', 'Guías para decidir sin depender de un vendedor', 'Escribimos sobre precios, pasarelas de pago, dominios .gt y errores comunes al contratar.', NULL, NULL, NULL, 'Ver todas las guías', '/blog/', '{\"limit\":3}', 11, 1),
  (37, 5, 'faq', 'Dudas frecuentes', 'Lo que nos preguntan antes de contratar', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12, 1),
  (38, 5, 'cta', NULL, 'Contanos qué necesita tu negocio', 'Escribinos por WhatsApp o dejanos tus datos. Te respondemos con una propuesta concreta: qué secciones, cuánto cuesta y en cuánto tiempo.', NULL, NULL, NULL, 'Escribir por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Llenar formulario\",\"cta2_url\":\"/contacto/\"}', 13, 1),
  (39, 6, 'page_hero', 'Nosotros', 'Quiénes somos', 'paginasweb.gt es la marca comercial con la que Servicom diseña páginas web y tiendas virtuales. Mismo equipo, mismo teléfono, mismo correo y el mismo compromiso desde 2007.', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (40, 6, 'rich_text', NULL, 'De dónde venimos', NULL, '<p>Servicom empezó en 2007 haciendo sitios para negocios que en ese momento apenas se estaban preguntando si valía la pena \"tener internet\". Eran otros tiempos: se diseñaba para pantallas de computadora, casi nadie navegaba desde el teléfono y el correo de la empresa todavía se leía en Outlook Express.</p>\n<p>En estos más de 18 años nos tocó adaptarnos varias veces: la llegada del celular como pantalla principal, la exigencia de velocidad, el certificado SSL como requisito, las redes sociales llevándose parte de la conversación y, más recientemente, la búsqueda por voz y los resúmenes automáticos de Google. Lo que no cambió es la parte del trabajo que de verdad decide si un sitio funciona: entender a qué se dedica el cliente y ordenar su información para que otra persona la entienda rápido.</p>\n<p>Hemos trabajado con bufetes, importadoras, distribuidoras de equipo industrial, clínicas, empresas de transporte, talleres y consultoras. En el <a href=\"/portafolio/\">portafolio</a> están los sitios que siguen en línea.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (41, 6, 'rich_text', NULL, 'Por qué usamos dos marcas', NULL, '<p>Conviene explicarlo claro, porque nos lo van a preguntar. <strong>Servicom</strong> es la empresa: el nombre con el que facturamos, con el que nos conocen clientes de hace más de una década y bajo el que seguimos atendiendo desde <a href=\"https://servicom.gt\" rel=\"noopener\">servicom.gt</a>. <strong>paginasweb.gt</strong> es la marca con la que presentamos específicamente el servicio de sitios y tiendas, con un nombre que describe lo que hacemos y que a la gente le queda más fácil recordar y dictar por teléfono.</p>\n<p>No son dos empresas, ni dos equipos, ni dos listas de precios. Es la misma gente, el mismo número de WhatsApp y el mismo correo. Si nos escribiste a Servicom hace tres años, te contesta la misma persona.</p>', NULL, NULL, NULL, NULL, NULL, 3, 1),
  (42, 6, 'features', 'Cómo trabajamos', 'Cuatro cosas que hacemos distinto', NULL, NULL, NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"chat\",\"title\":\"100% remoto, a propósito\",\"text\":\"No cobramos visitas ni te hacemos perder medio día en tráfico. Todo se resuelve por WhatsApp, correo y videollamada, y el proyecto avanza más rápido así.\"},{\"icon\":\"edit\",\"title\":\"Escribimos nosotros\",\"text\":\"La mayoría de proyectos se atrasan porque el cliente tiene que redactar. Nosotros escribimos con base en lo que nos contás y vos solo corregís.\"},{\"icon\":\"shield\",\"title\":\"Los accesos son tuyos\",\"text\":\"Dominio a nombre de tu empresa y entrega de credenciales cuando las pidás. Si un día te querés ir, te ayudamos a irte bien.\"},{\"icon\":\"search\",\"title\":\"Sin humo con el SEO\",\"text\":\"Hacemos bien la parte técnica y de contenido, y te explicamos qué depende de nosotros y qué depende del tiempo y de tu competencia.\"}]}', 4, 1),
  (43, 6, 'rich_text', NULL, 'En qué no creemos', NULL, '<p>No creemos en inflar cifras. No vas a leer aquí \"más de 500 clientes satisfechos\" ni un promedio de estrellas que nadie puede verificar. Publicamos el número de sitios que podés abrir y comprobar, y cuando tengamos testimonios de clientes reales dispuestos a firmarlos, los vamos a publicar con nombre y empresa.</p>\n<p>Tampoco creemos en las tácticas que dan un salto rápido en Google y un castigo después: llenar el pie de página con nombres de municipios, crear una página casi idéntica por cada palabra clave, comprar enlaces o esconder texto del mismo color que el fondo. Todo eso funcionó hace años y hoy es la forma más rápida de que un dominio nuevo pierda su oportunidad.</p>', NULL, NULL, NULL, NULL, NULL, 5, 1),
  (44, 6, 'cta', NULL, 'Hablemos de tu proyecto', 'Contanos qué hacés y qué querés lograr. Si podemos ayudarte, te lo decimos con precio y tiempo; si no, también.', NULL, NULL, NULL, 'Escribir por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Ir a contacto\",\"cta2_url\":\"/contacto/\"}', 6, 1),
  (45, 7, 'page_hero', 'Información legal', 'Política de privacidad', 'Qué datos recogemos en este sitio, para qué los usamos y cómo podés pedir que los eliminemos.', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (46, 7, 'legal_text', NULL, NULL, NULL, '<p class=\"lead\">Esta política explica qué información recolecta paginasweb.gt, marca comercial de Servicom, cuando visitás este sitio o nos escribís, para qué la usamos y qué podés pedirnos respecto de ella.</p>\n\n<h2>Quién trata tus datos</h2>\n<p>El responsable del tratamiento es Servicom, con operaciones en la ciudad de Guatemala. Para cualquier consulta sobre esta política podés escribirnos al correo de contacto publicado en la página de <a href=\"/contacto/\">contacto</a>.</p>\n\n<h2>Qué datos recolectamos</h2>\n<p><strong>Datos que nos das voluntariamente.</strong> Cuando llenás el formulario de cotización nos compartís tu nombre, tu correo electrónico, tu teléfono, el servicio que te interesa y el mensaje que escribís. Si nos contactás por WhatsApp o por teléfono, quedan los datos propios de esa conversación.</p>\n<p><strong>Datos técnicos de la visita.</strong> Como cualquier sitio, nuestro servidor registra la dirección IP, la fecha y hora de la visita, el navegador y las páginas consultadas. Esa información se usa para seguridad y para diagnosticar problemas.</p>\n<p><strong>Estadísticas de uso.</strong> Si están activadas las herramientas de analítica, se recopilan datos agregados sobre cómo se navega el sitio: páginas más vistas, tiempo de permanencia, tipo de dispositivo y país de origen. No usamos esa información para identificarte personalmente.</p>\n\n<h2>Para qué usamos la información</h2>\n<ul>\n  <li>Responder tu consulta y prepararte una propuesta.</li>\n  <li>Prestar y administrar el servicio si llegás a contratarnos.</li>\n  <li>Mantener la seguridad del sitio y prevenir abusos del formulario.</li>\n  <li>Entender cómo se usa el sitio para mejorarlo.</li>\n</ul>\n<p>No vendemos, alquilamos ni cedemos tus datos a terceros con fines comerciales, y no te vamos a suscribir a un boletín por haber llenado un formulario de cotización.</p>\n\n<h2>Cookies</h2>\n<p>Este sitio usa una cookie técnica de sesión, necesaria para el funcionamiento de los formularios y del panel de administración. Si están activadas las herramientas de analítica o de publicidad, esas herramientas pueden instalar sus propias cookies. Podés bloquear o eliminar cookies desde la configuración de tu navegador; el sitio sigue funcionando, aunque el envío de formularios podría verse afectado.</p>\n\n<h2>Con quién compartimos datos</h2>\n<p>Solo con proveedores necesarios para operar: el servicio de alojamiento donde vive este sitio y el servicio de correo por el que nos llegan tus mensajes. Si usamos herramientas de analítica de terceros, esos proveedores tratan datos técnicos conforme a sus propias políticas. También podríamos compartir información si una autoridad competente lo requiere legalmente.</p>\n\n<h2>Cuánto tiempo guardamos la información</h2>\n<p>Los mensajes recibidos por el formulario se conservan mientras sean útiles para la relación comercial. Si nos pedís que eliminemos tu consulta, lo hacemos. Los registros técnicos del servidor se conservan por períodos cortos, según la política del proveedor de alojamiento. La información de clientes activos se conserva mientras dure la relación y el tiempo adicional que exijan las obligaciones contables y fiscales.</p>\n\n<h2>Tus derechos</h2>\n<p>Podés pedirnos que te digamos qué datos tuyos tenemos, que los corrijamos si están equivocados o que los eliminemos. Escribinos desde el correo con el que nos contactaste y atendemos la solicitud en un plazo razonable.</p>\n\n<h2>Seguridad</h2>\n<p>El sitio opera bajo conexión cifrada (HTTPS), los accesos administrativos están protegidos con contraseñas cifradas y límite de intentos de acceso, y las consultas a la base de datos usan sentencias preparadas. Ningún sistema es infalible, pero aplicamos las medidas razonables para proteger la información.</p>\n\n<h2>Menores de edad</h2>\n<p>Este sitio está dirigido a personas que contratan servicios para su negocio. No solicitamos de forma consciente datos de menores de edad.</p>\n\n<h2>Cambios en esta política</h2>\n<p>Si actualizamos esta política, publicamos la nueva versión en esta misma dirección con su fecha de última actualización.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (47, 8, 'page_hero', 'Trabajos', 'Portafolio de sitios web', 'Preferimos mostrar sitios en línea antes que capturas de diseños que nunca se publicaron. Estos son proyectos de clientes que siguen activos: abrilos, probalos en tu teléfono y fijate en los tiempos de carga.', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (48, 8, 'rich_text', NULL, NULL, NULL, '<p>Verás sectores muy distintos: despachos legales, distribuidoras industriales, servicios a domicilio, transporte, salud y consultoría. Eso es a propósito. Un sitio de plomería de emergencia y el sitio de un bufete corporativo no se parecen en nada, porque la persona que llega a cada uno está en un momento distinto: una necesita el número ya, la otra quiere verificar trayectoria antes de escribir.</p>\n<p>En la mayoría de estos proyectos hicimos también la redacción de los textos, la preparación de las fotos y la configuración de dominio, correos y analítica. Si querés que te contemos cómo resolvimos alguno en particular, preguntanos y con gusto te explicamos las decisiones.</p>\n<p class=\"lead\" style=\"font-size:.95rem;color:var(--ink-50)\">Una aclaración: las imágenes de esta página son presentaciones ilustrativas de cada proyecto, no capturas automáticas. El enlace de cada tarjeta lleva al sitio real, que es donde conviene revisarlo.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (49, 8, 'portfolio_grid', NULL, 'Sitios publicados', NULL, NULL, NULL, NULL, NULL, NULL, '{\"limit\":0}', 3, 1),
  (50, 8, 'cta', NULL, '¿Te gustaría ver tu negocio en esta lista?', 'Contanos qué hacés y te proponemos la estructura que le sirve a tu tipo de negocio.', NULL, NULL, NULL, 'Escribir por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Pedir cotización\",\"cta2_url\":\"/contacto/\"}', 4, 1);
INSERT INTO page_sections (id, page_id, block_type, eyebrow, heading, subheading, body, image, image_alt, cta_text, cta_url, extra, sort_order, visible) VALUES
  (51, 9, 'page_hero', 'Precios 2026', 'Precios de páginas web en Guatemala', 'Una página web con nosotros cuesta Q1,250 al año y una tienda virtual Q1,750 al año. Los dos precios incluyen dominio, alojamiento con SSL, diseño, carga de contenido y soporte durante el año.', NULL, NULL, NULL, 'Cotizar mi proyecto', 'whatsapp', NULL, 1, 1),
  (52, 9, 'answer_box', NULL, '¿Cuánto cuesta una página web en Guatemala?', NULL, '<p>Una página web profesional en Guatemala cuesta <strong>Q1,250 al año</strong> con paginasweb.gt, e incluye el dominio, el alojamiento con certificado SSL, el diseño a la medida, la redacción de los textos, las cuentas de correo y el soporte durante los doce meses. Se arranca con un pago inicial de Q250 y el saldo de Q1,000 se paga al aprobar el diseño. Una <strong>tienda virtual</strong> cuesta <strong>Q1,750 al año</strong> (precio normal Q3,600), con un inicial de Q350 y un saldo de Q1,400. Si además querés cobrar con tarjeta, la integración con Visanet Epay agrega <strong>Q750 al año</strong>.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (53, 9, 'pricing_table', 'Comparativa', 'Los tres servicios, lado a lado', 'Elegí según lo que necesita tu negocio hoy. Se puede empezar con una página y agregar la tienda después.', NULL, NULL, NULL, NULL, NULL, NULL, 3, 1),
  (54, 9, 'rich_text', NULL, 'Cómo se paga', NULL, '<p>El esquema es sencillo y es el mismo para todos los clientes. Se hace un <strong>pago inicial</strong> para arrancar el proyecto (Q250 en página web, Q350 en tienda virtual). Ese pago cubre el registro del dominio, la configuración del alojamiento y el arranque del diseño. El <strong>saldo</strong> se paga cuando aprobás el diseño y antes de publicar. A partir de ahí, el servicio se renueva una vez al año.</p>\n<p>Aceptamos depósito y transferencia bancaria en quetzales. El primer pago funciona como aceptación de las condiciones del servicio, que podés leer completas en nuestros <a href=\"/terminos-y-condiciones/\">términos y condiciones</a>.</p>\n<p>No cobramos por reuniones, ni por revisiones dentro del proceso normal, ni por publicar el sitio. Lo que sí se cotiza aparte es lo que sale del alcance: rediseñar un sitio ya publicado, agregar módulos nuevos (citas, membresías, integraciones con otros sistemas), producción de fotografía o video, y campañas de publicidad.</p>', NULL, NULL, NULL, NULL, NULL, 4, 1),
  (55, 9, 'rich_text', NULL, 'Por qué hay tanta diferencia de precios en el mercado', NULL, '<p>Si pediste tres cotizaciones, seguro te dieron tres números muy distintos. No es que alguien esté mintiendo: es que \"página web\" describe cosas muy diferentes.</p>\n<p>Abajo de Q1,000 normalmente estás comprando una plantilla armada rápido, con textos genéricos y sin soporte real. Funciona como tarjeta de presentación y poco más. Entre Q1,000 y Q3,000 está el rango donde entra un sitio hecho a la medida para una pequeña o mediana empresa, con contenido propio y acompañamiento. Arriba de Q10,000 ya estás pagando desarrollo específico: integraciones con sistemas internos, portales con usuarios, aplicaciones web.</p>\n<p>La pregunta útil no es cuánto cuesta, sino qué incluye. Cuando compares cotizaciones, pedí que cada una responda lo mismo: ¿a nombre de quién queda el dominio? ¿el precio incluye el alojamiento del primer año? ¿quién escribe los textos? ¿cuántas revisiones entran? ¿qué pasa con el sitio si dejo de pagar? ¿me entregan los accesos si me quiero cambiar? Esas cinco respuestas explican casi toda la diferencia de precio.</p>', NULL, NULL, NULL, NULL, NULL, 5, 1),
  (56, 9, 'faq', 'Dudas de precio', 'Preguntas sobre precios y pagos', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, 1),
  (57, 9, 'related_links', NULL, 'Antes de decidir', NULL, NULL, NULL, NULL, NULL, NULL, '{\"links\":[{\"url\":\"/blog/cuanto-cuesta-una-pagina-web-en-guatemala/\",\"title\":\"Cuánto cuesta una página web en Guatemala en 2026\",\"text\":\"Rangos reales del mercado y qué explica cada salto de precio.\"},{\"url\":\"/blog/errores-al-contratar-diseno-web-guatemala/\",\"title\":\"7 errores al contratar diseño web\",\"text\":\"Las cláusulas y omisiones que salen caras después.\"},{\"url\":\"/diseno-de-paginas-web-guatemala/\",\"title\":\"Qué incluye el diseño\",\"text\":\"El detalle completo del servicio de página web.\"},{\"url\":\"/tiendas-virtuales-guatemala/\",\"title\":\"Qué incluye la tienda\",\"text\":\"Catálogo, envíos y cobro con tarjeta.\"}]}', 7, 1),
  (58, 9, 'cta', NULL, '¿Tu proyecto encaja en alguno de estos precios?', 'Contanos qué necesitás y te confirmamos el precio exacto antes de que pagués nada.', NULL, NULL, NULL, 'Consultar por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Pedir cotización\",\"cta2_url\":\"/contacto/\"}', 8, 1),
  (59, 10, 'page_hero', 'Ayuda', 'Preguntas frecuentes sobre sitios web', 'Juntamos lo que más nos preguntan por WhatsApp en estos años. Si tu duda no está acá, escribinos y la contestamos —y probablemente la agreguemos a esta página.', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (60, 10, 'faq_groups', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"groups\":[{\"title\":\"Antes de contratar\",\"slug\":\"preguntas-frecuentes\"},{\"title\":\"Precios y pagos\",\"slug\":\"precios\"},{\"title\":\"Páginas web\",\"slug\":\"diseno-de-paginas-web-guatemala\"},{\"title\":\"Tiendas en línea\",\"slug\":\"tiendas-virtuales-guatemala\"},{\"title\":\"Correo corporativo\",\"slug\":\"cuentas-de-correo-corporativo\"}]}', 2, 1),
  (61, 10, 'cta', NULL, '¿Tu duda no está en la lista?', 'Escribinos y te contestamos en horario de oficina, normalmente el mismo día.', NULL, NULL, NULL, 'Preguntar por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Escribir por formulario\",\"cta2_url\":\"/contacto/\"}', 3, 1),
  (62, 11, 'page_hero', 'Información legal', 'Términos y condiciones del servicio', 'Condiciones bajo las que contratás nuestros servicios de páginas web, tiendas virtuales y correo corporativo.', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1),
  (63, 11, 'legal_text', NULL, NULL, NULL, '<p class=\"lead\">Estas condiciones regulan la contratación de los servicios de diseño de páginas web, tiendas virtuales y correo corporativo que paginasweb.gt, marca comercial de Servicom, presta a sus clientes. El primer pago de cualquier servicio constituye la aceptación plena de estos términos.</p>\n\n<h2>1. Naturaleza del servicio</h2>\n<p>El servicio se contrata bajo la modalidad de <strong>suscripción anual</strong>. El precio publicado corresponde a doce meses de servicio e incluye, según el plan contratado: el diseño y la puesta en línea del sitio, el registro o la renovación de un dominio, el alojamiento web con certificado de seguridad, las cuentas de correo asociadas y el soporte técnico durante el período contratado.</p>\n<p>El servicio no incluye la producción de fotografía o video, la redacción de contenido especializado o técnico que requiera investigación externa, campañas de publicidad pagada, licencias de programas de terceros, ni el desarrollo de funciones no descritas en la propuesta aceptada. Cualquiera de estos elementos se cotiza por separado.</p>\n\n<h2>2. Precios, pagos y facturación</h2>\n<p>Todos los precios se expresan en quetzales (GTQ). La contratación inicia con un <strong>pago inicial</strong> que activa el proyecto y cubre el registro del dominio, la configuración del alojamiento y el arranque del diseño. El <strong>saldo</strong> se cancela al aprobar el diseño y previo a la publicación del sitio.</p>\n<p>Los pagos efectuados <strong>no son reembolsables</strong>, ya que desde el momento en que se recibe el pago inicial se incurre en costos de registro de dominio, provisión de alojamiento y horas de trabajo del equipo. Si el cliente decide no continuar, se le entrega el trabajo realizado hasta ese punto y el control del dominio registrado.</p>\n<p>Los precios pueden variar entre períodos. Cualquier ajuste se comunica antes de la fecha de renovación y nunca se aplica de forma retroactiva a un período ya pagado.</p>\n\n<h2>3. Renovación anual</h2>\n<p>El servicio se renueva por períodos de doce meses. Con anticipación al vencimiento se envía el aviso de renovación al correo registrado del cliente. La renovación mantiene activo el dominio, el alojamiento, el certificado de seguridad, las cuentas de correo y el soporte.</p>\n<p>Si el cliente no realiza el pago de renovación, el sitio y las cuentas de correo quedan suspendidos a partir de la fecha de vencimiento. Los archivos se conservan por un plazo prudencial durante el cual la reactivación es posible pagando el período correspondiente. Transcurrido ese plazo, la información puede eliminarse de forma definitiva de los servidores. Es responsabilidad del cliente conservar sus propios respaldos si desea preservar el contenido más allá de ese período.</p>\n\n<h2>4. Dominio</h2>\n<p>El dominio se registra a nombre de la empresa o la persona del cliente, quien es su titular. paginasweb.gt actúa únicamente como gestor técnico del registro y de la configuración DNS.</p>\n<p>El cliente puede solicitar en cualquier momento el traslado de su dominio a otro proveedor. En ese caso se entregan los códigos y accesos necesarios, siempre que el cliente esté al día en sus pagos y que el dominio no se encuentre dentro de períodos de bloqueo impuestos por el registrador, que son ajenos a nuestro control.</p>\n<p>La disponibilidad de un dominio depende del registrador correspondiente. Si el dominio solicitado no está disponible, se propone una alternativa sin costo adicional.</p>\n\n<h2>5. Contenido proporcionado por el cliente</h2>\n<p>El cliente declara ser titular de los derechos sobre los textos, logotipos, fotografías, videos y marcas que entrega para su publicación, o contar con autorización para usarlos. El cliente es el único responsable por reclamos de terceros derivados del material que proporciona.</p>\n<p>Nos reservamos el derecho de no publicar contenido ilegal, engañoso, que infrinja derechos de terceros o que contravenga las políticas de los proveedores de alojamiento.</p>\n\n<h2>6. Plazos de entrega</h2>\n<p>Los plazos indicados en la propuesta se cuentan a partir de la recepción del pago inicial y de la <strong>totalidad del material</strong> necesario (logotipo, fotografías, listado de servicios o productos y datos de contacto). Los retrasos en la entrega de material por parte del cliente corren la fecha de publicación en la misma proporción.</p>\n<p>El proyecto contempla rondas de revisión razonables dentro del alcance acordado. Cambios que modifiquen la estructura ya aprobada o que impliquen rehacer el diseño se cotizan aparte.</p>\n\n<h2>7. Soporte y alcance</h2>\n<p>Durante el período contratado se atienden consultas de soporte y cambios menores de contenido, como actualizar un precio, sustituir una fotografía, corregir un texto o agregar un elemento a una lista existente. El cliente también cuenta con acceso al panel de administración para realizar estos cambios por su cuenta.</p>\n<p>No se consideran soporte: rediseños completos, secciones nuevas, módulos adicionales, integraciones con sistemas de terceros, recuperación de sitios dañados por intervención de terceros ajenos a nuestro equipo, ni la capacitación reiterada del mismo personal.</p>\n\n<h2>8. Disponibilidad y limitación de responsabilidad</h2>\n<p>Trabajamos para mantener los sitios disponibles de forma continua, pero el servicio depende de proveedores de alojamiento y conectividad cuyas interrupciones no controlamos. No garantizamos disponibilidad ininterrumpida ni resultados comerciales específicos.</p>\n<p>De forma particular, no garantizamos posiciones determinadas en Google ni en ningún buscador. El posicionamiento depende de factores externos, entre ellos los algoritmos del buscador, la competencia del sector y el tiempo. Nuestro compromiso es aplicar buenas prácticas técnicas y de contenido, dentro de las políticas públicas de los buscadores.</p>\n<p>La responsabilidad total frente al cliente por cualquier reclamo relacionado con el servicio se limita al monto efectivamente pagado por el período vigente.</p>\n\n<h2>9. Protección de datos</h2>\n<p>Los datos que el cliente comparte se utilizan únicamente para prestar el servicio contratado y no se venden ni se ceden a terceros con fines comerciales. El detalle está en nuestra <a href=\"/politica-de-privacidad/\">política de privacidad</a>.</p>\n\n<h2>10. Portafolio</h2>\n<p>Salvo indicación escrita en contrario del cliente, podemos incluir el sitio entregado en nuestro portafolio, mencionando el nombre del proyecto y su dirección web. El cliente puede solicitar su retiro en cualquier momento.</p>\n\n<h2>11. Terminación</h2>\n<p>Cualquiera de las partes puede dar por terminada la relación al final del período contratado, notificándolo antes de la fecha de renovación. La terminación no genera reembolso del período en curso. A solicitud del cliente se entregan los archivos del sitio y los accesos correspondientes.</p>\n\n<h2>12. Modificaciones</h2>\n<p>Estas condiciones pueden actualizarse. La versión vigente es la publicada en esta página, con su fecha de última actualización. Los cambios sustanciales se comunican por correo a los clientes activos.</p>\n\n<h2>13. Legislación y jurisdicción</h2>\n<p>Estas condiciones se rigen por las leyes de la República de Guatemala. Para cualquier controversia, las partes se someten a los tribunales competentes de la ciudad de Guatemala, renunciando a cualquier otro fuero.</p>\n\n<h2>14. Aceptación</h2>\n<p>La realización del primer pago, por cualquier medio, implica que el cliente leyó, entendió y acepta estas condiciones en su totalidad.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (64, 12, 'page_hero', 'Servicio', 'Tiendas virtuales en Guatemala', 'Montamos tu tienda sobre WooCommerce con el catálogo cargado, opciones de envío para el interior y la posibilidad de cobrar con tarjeta a través de Visanet Epay. Vos administrás productos, precios y pedidos.', NULL, '/assets/img/servicio-tiendas-virtuales.svg', 'Ilustración de una tienda en línea con carrito de compras', 'Quiero mi tienda', 'whatsapp', '{\"cta2_text\":\"Ver precio\",\"cta2_url\":\"/precios/\"}', 1, 1),
  (65, 12, 'rich_text', NULL, 'Cuándo conviene una tienda y cuándo no', NULL, '<p>Una tienda en línea tiene sentido cuando vendés productos con precio definido, tenés existencias que podés controlar y ya estás recibiendo pedidos por mensaje. Si vendés servicios que se cotizan caso por caso, o si tu catálogo cambia de precio cada semana según el tipo de cambio, probablemente te sirva más una página web con catálogo y cotización que una tienda con carrito.</p>\n<p>Lo decimos antes de venderte: una tienda mal usada es peor que no tenerla. Un carrito con existencias desactualizadas genera pedidos que no podés cumplir, y eso cuesta clientes. Por eso, en la primera conversación revisamos cuántos productos tenés, quién va a mantener el inventario y cómo hacés los envíos hoy. Si la respuesta es que nadie tiene tiempo de actualizar nada, te proponemos empezar con un catálogo sin carrito.</p>\n<p>Cuando sí conviene, la diferencia se nota rápido: el cliente arma su pedido solo, ve el costo del envío antes de confirmar, y a vos te llega el pedido completo con dirección y forma de pago, en vez de una conversación de cuarenta mensajes.</p>', NULL, NULL, NULL, NULL, NULL, 2, 1),
  (66, 12, 'features', 'Qué incluye', 'Lo que lleva tu tienda desde el día uno', NULL, NULL, NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"cart\",\"title\":\"WooCommerce sobre WordPress\",\"text\":\"La plataforma de comercio más usada del mundo, instalada en tu propio alojamiento. Sin comisión por venta ni renta mensual de plataforma.\"},{\"icon\":\"box\",\"title\":\"Catálogo cargado por nosotros\",\"text\":\"Subimos tus primeros productos con categorías, fotos, descripciones, precios, variantes (talla, color, presentación) y control de existencias.\"},{\"icon\":\"truck\",\"title\":\"Envíos configurados para Guatemala\",\"text\":\"Tarifas distintas para la capital y el interior, retiro en tienda y envío gratis a partir de cierto monto, si así lo querés manejar.\"},{\"icon\":\"card\",\"title\":\"Formas de pago locales\",\"text\":\"Depósito o transferencia bancaria con carga de comprobante, pago contra entrega y, opcionalmente, tarjeta con Visanet Epay.\"},{\"icon\":\"phone\",\"title\":\"Optimizada para el celular\",\"text\":\"La mayoría de las compras en Guatemala se hacen desde el teléfono. El proceso de compra está pensado para completarse con una mano.\"},{\"icon\":\"edit\",\"title\":\"Panel para tu equipo\",\"text\":\"Agregar productos, cambiar precios, ver pedidos y marcar entregas. Con capacitación por videollamada incluida.\"},{\"icon\":\"chat\",\"title\":\"WhatsApp como respaldo\",\"text\":\"Botón visible en todo el sitio, porque en Guatemala mucha gente quiere confirmar por mensaje antes de pagar.\"},{\"icon\":\"chart\",\"title\":\"Medición de ventas\",\"text\":\"Configuramos la analítica para que sepas qué productos se ven más y en qué paso se caen los pedidos.\"}]}', 3, 1),
  (67, 12, 'rich_text', NULL, 'Cobro con tarjeta en Guatemala: cómo funciona de verdad', NULL, '<p>Esta es la parte que más confunde, así que vale explicarla con calma. Para cobrar con tarjeta en tu sitio intervienen tres cosas distintas: la tienda, la pasarela y el banco.</p>\n<p>La <strong>tienda</strong> es tu sitio con WooCommerce. La <strong>pasarela</strong> es el servicio que procesa la tarjeta de forma segura sin que los datos pasen por tu servidor: en Guatemala, la opción más usada es Visanet Epay. Y el <strong>banco adquirente</strong> es quien te afilia al servicio, define tu comisión por transacción y deposita el dinero en tu cuenta.</p>\n<p>Nosotros hacemos la parte técnica: integramos Epay a tu tienda, configuramos el ambiente de pruebas, hacemos compras de prueba y dejamos el cobro funcionando. Ese trabajo tiene un costo adicional de Q750 al año, que cubre la integración y su mantenimiento. Lo que no podemos hacer por vos es la afiliación: el contrato con el banco lo firma tu empresa, y la comisión por transacción la negociás vos directamente. Te acompañamos en el trámite y les damos a los ejecutivos los datos técnicos que suelen pedir.</p>\n<p>Un consejo por experiencia: no arranques con tarjeta si todavía no tenés volumen de pedidos. Empezá con transferencia y contra entrega, medí cuántos pedidos reales entran al mes y activá la tarjeta cuando el número justifique la afiliación. Muchos negocios pagan por una pasarela que procesa tres pagos al mes.</p>', NULL, NULL, NULL, NULL, NULL, 4, 1),
  (68, 12, 'features', 'Antes de arrancar', 'Lo que necesitás tener listo', NULL, '<p>Mientras más completo llegue esto, más rápido sale la tienda.</p>', NULL, NULL, NULL, NULL, '{\"items\":[{\"icon\":\"box\",\"title\":\"Listado de productos\",\"text\":\"En una hoja de cálculo: nombre, descripción corta, precio, categoría y variantes. No hace falta que esté perfecto, pero sí completo.\"},{\"icon\":\"image\",\"title\":\"Fotos de producto\",\"text\":\"Una foto por producto como mínimo, sobre fondo claro y parejo. Con un celular reciente y luz de día alcanza.\"},{\"icon\":\"truck\",\"title\":\"Reglas de envío\",\"text\":\"Cuánto cobrás a la capital, cuánto al interior, si hacés envío gratis desde cierto monto y con qué empresa despachás.\"},{\"icon\":\"file\",\"title\":\"Datos fiscales\",\"text\":\"Cómo facturás los pedidos. Si emitís factura electrónica, definimos desde el inicio cómo se conecta con el flujo de pedidos.\"}]}', 5, 1),
  (69, 12, 'pricing_service', 'Inversión', 'Precio de la tienda virtual', 'Precio anual con dominio, alojamiento, SSL y soporte incluidos.', NULL, NULL, NULL, NULL, NULL, NULL, 6, 1),
  (70, 12, 'related_links', NULL, 'Seguí leyendo', NULL, NULL, NULL, NULL, NULL, NULL, '{\"links\":[{\"url\":\"/blog/como-crear-tienda-en-linea-guatemala/\",\"title\":\"Cómo crear una tienda en línea en Guatemala\",\"text\":\"Guía paso a paso, desde el dominio hasta el primer pedido.\"},{\"url\":\"/blog/como-cobrar-con-tarjeta-sitio-web-guatemala/\",\"title\":\"Cómo cobrar con tarjeta en tu sitio\",\"text\":\"Pasarelas disponibles, comisiones y qué pide el banco.\"},{\"url\":\"/blog/woocommerce-vs-shopify-guatemala/\",\"title\":\"WooCommerce o Shopify\",\"text\":\"Comparación con números reales para un negocio guatemalteco.\"},{\"url\":\"/precios/\",\"title\":\"Precios\",\"text\":\"Comparativa de los tres servicios en una sola tabla.\"}]}', 7, 1),
  (71, 12, 'faq', 'Preguntas', 'Dudas sobre tiendas en línea', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, 1),
  (72, 12, 'cta', NULL, 'Contanos qué vendés y te decimos qué necesitás', 'Revisamos tu catálogo y te damos una propuesta concreta, con precio y tiempo de entrega.', NULL, NULL, NULL, 'Escribir por WhatsApp', 'whatsapp', '{\"cta2_text\":\"Llenar formulario\",\"cta2_url\":\"/contacto/\"}', 9, 1);
INSERT INTO faqs (id, page_slug, question, answer, sort_order, visible) VALUES
  (1, '', '¿Cuánto cuesta una página web en Guatemala?', '<p>Con nosotros, una página web profesional cuesta Q1,250 al año e incluye dominio, alojamiento con SSL, diseño a la medida, redacción de textos, cuentas de correo y soporte. Se arranca con Q250 y el saldo de Q1,000 se paga al aprobar el diseño. El detalle completo está en la página de <a href=\"/precios/\">precios</a>.</p>', 1, 1),
  (2, '', '¿En cuánto tiempo entregan un sitio?', '<p>Un sitio corporativo estándar toma entre dos y tres semanas desde que tenemos el pago inicial y el material completo (logo, fotos y listado de servicios). Lo que más atrasa los proyectos no es el diseño, sino esperar la información del cliente.</p>', 2, 1),
  (3, '', '¿El dominio queda a nombre de mi empresa?', '<p>Sí. El dominio se registra a nombre de tu empresa o tuyo, y vos sos el titular. Nosotros solo lo administramos técnicamente. Si algún día querés llevarlo a otro proveedor, te damos los códigos de traslado.</p>', 3, 1),
  (4, '', '¿Puedo editar el contenido yo mismo?', '<p>Sí. Entregamos un panel de administración en español donde podés cambiar textos, precios, fotos, publicaciones del blog y datos de contacto. Damos una capacitación por videollamada para que lo uses sin miedo.</p>', 4, 1),
  (5, '', '¿Trabajan con clientes fuera de la capital o del país?', '<p>Sí. Todo el proceso es en línea: WhatsApp, correo y videollamada. Tenemos clientes en varios departamentos y también guatemaltecos que operan desde el extranjero.</p>', 5, 1),
  (6, '', '¿Garantizan el primer lugar en Google?', '<p>No, y desconfiá de quien lo prometa. Lo que sí hacemos es dejar bien la parte técnica y de contenido: velocidad, estructura, títulos, datos estructurados y mapa del sitio. El posicionamiento depende además de tu competencia y del tiempo, y eso no lo controla ninguna agencia.</p>', 6, 1),
  (7, 'precios', '¿El precio de Q1,250 es por año o por una sola vez?', '<p>Es anual. Cubre doce meses de servicio e incluye dominio, alojamiento, certificado SSL, correos y soporte. Al año siguiente se renueva para mantener todo activo.</p>', 1, 1),
  (8, 'precios', '¿Cómo se hacen los pagos?', '<p>Con un pago inicial que activa el proyecto (Q250 en página web, Q350 en tienda virtual) y el saldo al aprobar el diseño, antes de publicar. Aceptamos depósito y transferencia bancaria en quetzales.</p>', 2, 1),
  (9, 'precios', '¿Qué pasa si no renuevo al año siguiente?', '<p>El sitio y los correos quedan suspendidos al vencer el período. Conservamos los archivos un tiempo prudencial por si querés reactivar. El dominio sigue siendo tuyo y te entregamos los accesos para trasladarlo.</p>', 3, 1),
  (10, 'precios', '¿Cobran extra por cambios en el sitio?', '<p>Los cambios menores están incluidos y además podés hacerlos vos desde el panel. Se cotizan aparte los rediseños completos, las secciones nuevas y las funciones adicionales, como un sistema de citas o una integración con otro sistema.</p>', 4, 1),
  (11, 'precios', '¿Los precios incluyen IVA?', '<p>Los precios publicados son los que se facturan. Al momento de cotizar te confirmamos por escrito el monto exacto y la forma de facturación, para que no haya sorpresas.</p>', 5, 1),
  (12, 'precios', '¿Por qué la tienda aparece con precio tachado de Q3,600?', '<p>Q3,600 es el precio normal de la tienda virtual. Q1,750 es el precio de lanzamiento con el que estamos trabajando actualmente. Cuando ese precio cambie, lo actualizamos en esta misma página.</p>', 6, 1),
  (13, 'diseno-de-paginas-web-guatemala', '¿Usan plantillas o diseñan desde cero?', '<p>Partimos de nuestro propio sistema de diseño y lo adaptamos a cada negocio: colores, tipografía, estructura de secciones y fotografías. No compramos plantillas de catálogo que ya estén usando otros negocios en Guatemala.</p>', 1, 1),
  (14, 'diseno-de-paginas-web-guatemala', '¿Cuántas páginas incluye el sitio?', '<p>Las que tenga sentido incluir según tu negocio. Un sitio corporativo típico lleva inicio, servicios, nosotros, portafolio, preguntas frecuentes y contacto. Si un servicio tuyo merece su propia página porque la gente lo busca por separado, la hacemos.</p>', 2, 1),
  (15, 'diseno-de-paginas-web-guatemala', '¿Quién escribe los textos?', '<p>Nosotros. Vos nos contás a qué te dedicás y qué te preguntan tus clientes, y con eso redactamos. Después revisás y corregís lo que solo vos sabés: nombres técnicos, garantías, cobertura y condiciones.</p>', 3, 1),
  (16, 'diseno-de-paginas-web-guatemala', '¿Qué pasa si no tengo fotos de mi negocio?', '<p>Te decimos exactamente qué fotos tomar y cómo, para que con un celular reciente y luz de día tengas material aprovechable. Para lo que no se puede fotografiar usamos ilustraciones propias. No usamos fotos de bancos de imágenes que ya estén en otros veinte sitios.</p>', 4, 1),
  (17, 'diseno-de-paginas-web-guatemala', '¿Puedo mover mi sitio actual con ustedes?', '<p>Sí, siempre que tengás los accesos. Revisamos qué se puede aprovechar del contenido, migramos el sitio o lo rehacemos según convenga, y configuramos las redirecciones para no perder el posicionamiento que ya tenías.</p>', 5, 1),
  (18, 'diseno-de-paginas-web-guatemala', '¿El sitio funciona bien en celular?', '<p>Sí, y es lo primero que diseñamos. Probamos el sitio en anchos de 360, 390, 768, 1024 y 1440 píxeles antes de publicar, porque la mayoría de tus visitas van a llegar desde un teléfono.</p>', 6, 1),
  (19, 'tiendas-virtuales-guatemala', '¿Qué plataforma usan para las tiendas?', '<p>WooCommerce sobre WordPress, instalado en tu propio alojamiento. Es la plataforma de comercio más usada del mundo, no cobra comisión por venta y te deja llevarte la tienda a donde quieras.</p>', 1, 1),
  (20, 'tiendas-virtuales-guatemala', '¿Cuánto cuesta poder cobrar con tarjeta?', '<p>La integración con Visanet Epay cuesta Q750 al año adicionales al plan de tienda. Aparte, tu empresa debe afiliarse con el banco, que define la comisión por transacción. Esa afiliación se contrata directamente con la entidad bancaria.</p>', 2, 1),
  (21, 'tiendas-virtuales-guatemala', '¿Cuántos productos puedo subir?', '<p>No ponemos un límite artificial. Nosotros cargamos un primer grupo de productos para dejar la tienda funcionando y capacitarte, y de ahí en adelante vos podés seguir agregando los que necesités desde el panel.</p>', 3, 1),
  (22, 'tiendas-virtuales-guatemala', '¿Cómo se manejan los envíos?', '<p>Configuramos tarifas distintas para la capital y el interior, retiro en tienda y, si querés, envío gratis a partir de cierto monto. El cliente ve el costo del envío antes de confirmar el pedido.</p>', 4, 1),
  (23, 'tiendas-virtuales-guatemala', '¿La tienda emite factura electrónica?', '<p>WooCommerce genera el comprobante del pedido, que no es lo mismo que una factura FEL. Para emitir factura electrónica se necesita un proveedor certificado por la SAT. Podemos revisar con vos las opciones y cómo encajarlas en el flujo de pedidos.</p>', 5, 1),
  (24, 'tiendas-virtuales-guatemala', '¿Me sirve una tienda si vendo servicios?', '<p>Depende. Si tu servicio tiene precio fijo y se puede pagar por adelantado, sí. Si cada trabajo se cotiza aparte, normalmente te sirve más una página web con catálogo y formulario de cotización. Te lo decimos antes de venderte la tienda.</p>', 6, 1),
  (25, 'cuentas-de-correo-corporativo', '¿Necesito una página web para tener correo con mi dominio?', '<p>No necesariamente. Se puede configurar el correo con tu dominio aunque todavía no tengás sitio. Ahora bien, si ya vas a pagar dominio y alojamiento, el paso a tener también la página es corto.</p>', 1, 1);
INSERT INTO faqs (id, page_slug, question, answer, sort_order, visible) VALUES
  (26, 'cuentas-de-correo-corporativo', '¿Por qué mis correos caen en spam?', '<p>Casi siempre es porque faltan los registros SPF y DKIM del dominio, o porque se está enviando desde una dirección IP con mala reputación. Revisamos ambas cosas y dejamos la configuración correcta.</p>', 2, 1),
  (27, 'cuentas-de-correo-corporativo', '¿Puedo seguir usando Gmail para leer mi correo de empresa?', '<p>Sí. Se puede configurar tu cuenta corporativa dentro de la aplicación de Gmail o de cualquier otro cliente de correo, para que escribas desde tu dominio pero sigas usando la interfaz que ya conocés.</p>', 3, 1),
  (28, 'cuentas-de-correo-corporativo', '¿Migran los correos que ya tengo?', '<p>Cuando la plataforma de origen lo permite, sí: trasladamos las cuentas y el historial. Coordinamos el cambio para que la interrupción sea mínima y te avisamos qué hacer durante la transición.</p>', 4, 1),
  (29, 'preguntas-frecuentes', '¿Qué diferencia hay entre paginasweb.gt y Servicom?', '<p>Ninguna en cuanto a equipo, precios y contacto: paginasweb.gt es la marca comercial con la que Servicom presenta su servicio de sitios y tiendas. Mismo teléfono, mismo correo, mismas personas. Podés leer más en <a href=\"/nosotros/\">Nosotros</a>.</p>', 1, 1),
  (30, 'preguntas-frecuentes', '¿Hacen aplicaciones móviles o sistemas a la medida?', '<p>No. Nos dedicamos a sitios web, tiendas en línea y correo corporativo. Si tu proyecto es una aplicación o un sistema interno, te lo decimos de una vez en lugar de aceptar algo que no es lo nuestro.</p>', 2, 1),
  (31, 'preguntas-frecuentes', '¿Manejan publicidad en Google o Facebook?', '<p>No gestionamos campañas pagadas. Dejamos el sitio y la analítica listos para que quien maneje tu publicidad pueda medir resultados sin problemas.</p>', 3, 1),
  (32, 'preguntas-frecuentes', '¿Firman contrato?', '<p>La relación se rige por los <a href=\"/terminos-y-condiciones/\">términos y condiciones</a> publicados, que se aceptan con el primer pago. Si tu empresa necesita un documento firmado para su proceso interno, lo preparamos sin problema.</p>', 4, 1),
  (33, 'preguntas-frecuentes', '¿Qué pasa si mi sitio se cae o lo hackean?', '<p>Contás con soporte durante el período contratado. Restauramos desde los respaldos del alojamiento y revisamos qué lo causó. Si el problema vino de una intervención de terceros ajenos a nuestro equipo, la recuperación se cotiza aparte.</p>', 5, 1),
  (34, 'preguntas-frecuentes', '¿Me entregan los accesos si me quiero cambiar de proveedor?', '<p>Sí. Estando al día en pagos, te entregamos los archivos del sitio y los accesos del dominio. Nunca hemos considerado que retener un dominio sea una forma decente de conservar un cliente.</p>', 6, 1);
INSERT INTO posts (id, slug, title, excerpt, body, image, image_alt, category_id, author, published_at, updated_at, meta_title, meta_description, robots_index, visible) VALUES
  (1, 'como-cobrar-con-tarjeta-sitio-web-guatemala', 'Cómo cobrar con tarjeta en tu sitio web en Guatemala', 'Pasarelas disponibles, el trámite de afiliación, las comisiones reales y cuándo conviene esperar antes de activarlo.', '<p>\"Quiero que la gente pueda pagar con tarjeta en mi página.\" Es una de las peticiones más frecuentes y también una de las que más confusión genera, porque intervienen tres actores distintos y casi nadie explica cuál hace qué.</p>\n<p>Vamos por partes, con lo que aplica específicamente en Guatemala.</p>\n\n<h2>Los tres actores del cobro con tarjeta</h2>\n<ol>\n  <li><strong>Tu sitio o tienda.</strong> Donde el cliente arma el pedido y llega al momento de pagar.</li>\n  <li><strong>La pasarela de pago.</strong> El servicio que recibe los datos de la tarjeta de forma segura, los valida y devuelve una respuesta. Los datos de la tarjeta nunca deberían pasar por tu servidor.</li>\n  <li><strong>El banco adquirente.</strong> La entidad que te afilia al servicio, define tu comisión por transacción y deposita el dinero en tu cuenta.</li>\n</ol>\n<p>Necesitás los tres. Un proveedor web puede resolver el primero y conectar el segundo, pero el tercero lo contrata tu empresa directamente. Nadie puede afiliarte por vos.</p>\n\n<h2>Qué opciones hay en Guatemala</h2>\n\n<h3>Visanet Epay</h3>\n<p>Es la pasarela más usada en el país para comercio electrónico y la que integramos por defecto. Se conecta con las tiendas más comunes, procesa Visa y Mastercard en quetzales y funciona con la afiliación que gestionás a través de tu banco. Es la opción más previsible: los bancos la conocen, los ejecutivos saben qué es y los tiempos de trámite son razonables.</p>\n\n<h3>Pasarelas de bancos locales</h3>\n<p>Varios bancos guatemaltecos ofrecen su propia solución de comercio electrónico a clientes empresariales. Si ya tenés cuenta y buena relación con tu banco, vale la pena preguntar: a veces la comisión que negociás como cliente conocido es mejor que la estándar.</p>\n\n<h3>Plataformas de cobro en línea de origen local</h3>\n<p>En los últimos años surgieron opciones guatemaltecas pensadas para cobrar en línea sin el trámite tradicional de afiliación, con enlaces de pago y suscripciones. Suelen tener comisiones más altas por transacción, pero se activan mucho más rápido y sirven bien para empezar o para cobrar servicios recurrentes. Revisá condiciones vigentes antes de decidir, porque este mercado se mueve.</p>\n\n<h3>PayPal</h3>\n<p>Funciona para recibir pagos, sobre todo del extranjero. La limitación histórica en Guatemala está en el retiro de fondos hacia cuentas locales, que no siempre es directo ni inmediato. Es un buen complemento si vendés a clientes fuera del país, no un reemplazo de la pasarela local.</p>\n\n<h3>Lo que no está disponible</h3>\n<p>Conviene decirlo claro para ahorrarte tiempo: Stripe no opera en Guatemala, y Shopify Payments tampoco. Si leíste una guía que recomienda cualquiera de los dos, estaba escrita para otro país. Es una de las razones por las que muchas tiendas guatemaltecas terminan en WooCommerce, como explicamos en <a href=\"/blog/woocommerce-vs-shopify-guatemala/\">esta comparación</a>.</p>\n\n<h2>Cómo es el trámite de afiliación</h2>\n<p>El banco va a pedirte, en términos generales:</p>\n<ul>\n  <li>Documentación legal de la empresa: patente de comercio, escritura de constitución y representación legal.</li>\n  <li>Registro tributario vigente ante la SAT.</li>\n  <li>Cuenta bancaria empresarial en la misma entidad.</li>\n  <li>La dirección de tu sitio, ya funcionando, con información visible sobre productos, precios, políticas de envío, política de devoluciones y datos de contacto.</li>\n  <li>Estimación de tu volumen mensual y ticket promedio.</li>\n</ul>\n<p>Ese punto del sitio funcionando es importante: el banco revisa tu página antes de aprobar. Si tu tienda no tiene política de devoluciones publicada ni datos de contacto claros, la solicitud se atrasa. Cuando montamos una tienda dejamos esas páginas listas justamente para que el trámite no se trabe ahí.</p>\n<p>Los tiempos varían bastante entre bancos. Planificá semanas, no días, y no anuncies el cobro con tarjeta hasta tenerlo aprobado y probado.</p>\n\n<h2>Las comisiones: qué esperar</h2>\n<p>Cada banco negocia sus tarifas, así que no existe un número único. Lo que sí es constante es la estructura:</p>\n<ul>\n  <li>Un <strong>porcentaje por transacción</strong>, que en comercio electrónico suele ser mayor que en un datáfono físico, porque el riesgo de contracargo es más alto.</li>\n  <li>A veces un <strong>monto fijo</strong> por operación.</li>\n  <li>Posiblemente una <strong>renta mensual</strong> del servicio de pasarela.</li>\n  <li>El <strong>plazo de liquidación</strong>: cuántos días tarda el dinero en llegar a tu cuenta.</li>\n</ul>\n<p>Pedí siempre estos cuatro datos por escrito antes de firmar, y hacé la cuenta con tu ticket promedio real. Si vendés productos de Q80 y la comisión combinada te come el 5%, hay que revisar si el precio lo aguanta.</p>\n\n<h2>Lo que agrega el proveedor web</h2>\n<p>Nuestra parte es técnica: instalar el módulo de la pasarela en tu tienda, configurar las credenciales, hacer compras de prueba en el ambiente de pruebas y luego en producción, verificar que los pedidos se registren correctamente y que los correos de confirmación salgan. En nuestro servicio eso cuesta Q750 al año, que además cubre el mantenimiento de la integración cuando la pasarela actualiza sus requisitos.</p>\n<p>También configuramos las páginas que el banco exige revisar y dejamos el sitio con certificado SSL activo, que es requisito indispensable.</p>\n\n<h2>¿Conviene activarlo desde el día uno?</h2>\n<p>Normalmente no, y esta es la parte donde vamos en contra de nuestro propio interés comercial.</p>\n<p>Si estás empezando a vender en línea, arrancá con transferencia bancaria con carga de comprobante y pago contra entrega. Son gratis, en Guatemala la gente las usa con toda naturalidad y te permiten medir demanda real. Cuando lleves dos o tres meses con pedidos constantes, hacé la cuenta: si el volumen y el ticket promedio justifican la comisión, activás la tarjeta. Hemos visto negocios pagando una pasarela para procesar tres pagos al mes.</p>\n<p>La excepción es si vendés productos de precio alto, si tu cliente es corporativo o si vendés al extranjero. En esos casos el cobro con tarjeta sí cambia la conversión desde el inicio.</p>\n\n<h2>Contracargos: lo que nadie te advierte</h2>\n<p>Un contracargo ocurre cuando el titular de la tarjeta desconoce un cobro y el banco le devuelve el dinero. En comercio electrónico pasa más que en tienda física, porque no hay firma ni tarjeta presente.</p>\n<p>Para reducir el riesgo: guardá el comprobante de entrega de cada pedido, mandá correos de confirmación con el detalle, publicá tu política de devoluciones y usá el nombre comercial correcto en el estado de cuenta, para que el cliente reconozca el cargo. Muchos contracargos no son fraude, sino gente que no recuerda dónde compró.</p>\n\n<h2>Resumen</h2>\n<p>Cobrar con tarjeta en Guatemala requiere tres piezas: la tienda, la pasarela y la afiliación bancaria. La opción más establecida es Visanet Epay; Stripe y Shopify Payments no aplican acá. El trámite toma semanas y el banco revisa tu sitio, así que conviene tenerlo completo antes de solicitar. Y salvo casos específicos, conviene empezar con transferencia y contra entrega y activar la tarjeta cuando el volumen lo justifique.</p>\n<p>Si querés que revisemos tu caso o que preparemos tu sitio para la solicitud del banco, <a href=\"/contacto/\">escribinos</a>.</p>', '/assets/img/blog/cobrar-con-tarjeta-guatemala.svg', 'Ilustración de un pago con tarjeta en una tienda en línea', 3, 'Equipo de paginasweb.gt', '2026-04-08 09:00:00', '2026-04-08 09:00:00', 'Cómo Cobrar con Tarjeta en tu Sitio Web en Guatemala', 'Qué pasarelas de pago funcionan en Guatemala, cómo es la afiliación con el banco, qué comisiones esperar y cuándo conviene activar el cobro con tarjeta.', 1, 1),
  (2, 'como-crear-tienda-en-linea-guatemala', 'Cómo crear una tienda en línea en Guatemala paso a paso', 'Los nueve pasos reales, con las decisiones de envío, pago y facturación que solo aplican en el país.', '<p>Vender en línea en Guatemala no es lo mismo que en México o en España, y las guías que se encuentran en internet casi siempre están escritas para otro país. Acá hay particularidades concretas: cómo cobra la gente, qué esperan del envío al interior, qué pide la SAT y qué pasarelas de pago funcionan de verdad.</p>\n<p>Esta guía es el orden en que nosotros montamos una tienda, con las decisiones que hay que tomar en cada paso.</p>\n\n<h2>Paso 1: Confirmá que tu negocio está listo</h2>\n<p>Antes de gastar un quetzal, contestá tres preguntas honestamente:</p>\n<ul>\n  <li><strong>¿Podés controlar tu inventario?</strong> Si no sabés cuántas unidades tenés de cada producto, la tienda va a generar pedidos que no vas a poder cumplir. Eso cuesta clientes y reseñas.</li>\n  <li><strong>¿Alguien va a mantener la tienda?</strong> Actualizar precios, marcar productos agotados, revisar pedidos. Media hora al día como mínimo.</li>\n  <li><strong>¿Tenés cómo despachar?</strong> Aunque sea un acuerdo con un mensajero. Sin logística resuelta, la tienda solo traslada el problema.</li>\n</ul>\n<p>Si alguna respuesta es no, empezá con un catálogo en línea sin carrito, donde la gente pide por WhatsApp. Es un paso intermedio perfectamente válido.</p>\n\n<h2>Paso 2: Elegí y registrá el dominio</h2>\n<p>El nombre de tu tienda en internet. Para vender a Guatemala, un <code>.com</code> funciona bien y es lo más económico; un <code>.gt</code> o <code>.com.gt</code> transmite cercanía local. Lo importante es que sea corto, fácil de dictar por teléfono y sin guiones ni números.</p>\n<p>Registralo a nombre de tu empresa, no del proveedor que te arma la tienda. Es tu activo. Escribimos aparte sobre <a href=\"/blog/dominio-gt-como-registrarlo/\">cómo funciona el dominio .gt y cómo registrarlo</a>.</p>\n\n<h2>Paso 3: Escogé la plataforma</h2>\n<p>Las opciones realistas para un negocio guatemalteco son tres:</p>\n<ul>\n  <li><strong>WooCommerce</strong> sobre WordPress. Se instala en tu propio alojamiento, no cobra comisión por venta y podés llevártelo a donde quieras. Es lo que usamos nosotros.</li>\n  <li><strong>Shopify.</strong> Renta mensual en dólares, muy fácil de usar, pero con limitaciones para integrar pasarelas locales. Lo comparamos a fondo en <a href=\"/blog/woocommerce-vs-shopify-guatemala/\">WooCommerce o Shopify para negocios en Guatemala</a>.</li>\n  <li><strong>Marketplaces</strong> como Kemik o los perfiles de compra de redes sociales. Sirven para probar demanda sin inversión, pero no son tuyos y las reglas las pone otro.</li>\n</ul>\n<p>Un consejo: podés estar en un marketplace y tener tu tienda propia al mismo tiempo. No son excluyentes.</p>\n\n<h2>Paso 4: Contratá alojamiento que aguante</h2>\n<p>Una tienda pesa más que una página informativa y hace consultas constantes a la base de datos. El plan de alojamiento más barato del mercado no va a servir: cuando lances una promoción y entren cincuenta personas a la vez, la tienda se cae justo el día que más te importa.</p>\n<p>Buscá un plan con certificado SSL incluido, respaldos automáticos y soporte que conteste. Si tu público está en Guatemala, un servidor en Estados Unidos funciona bien; la diferencia de milisegundos con un servidor local no se nota.</p>\n\n<h2>Paso 5: Armá el catálogo bien desde el inicio</h2>\n<p>Este paso decide si tu tienda vende o no. Cada producto necesita:</p>\n<ul>\n  <li><strong>Nombre claro,</strong> como lo busca la gente, no como lo llaman internamente en tu bodega.</li>\n  <li><strong>Foto propia,</strong> sobre fondo claro y parejo. Con un celular reciente y luz de día alcanza. Evitá las fotos que el proveedor te manda por WhatsApp con su marca de agua.</li>\n  <li><strong>Descripción que responda dudas:</strong> medidas, material, contenido del empaque, garantía, para qué sirve.</li>\n  <li><strong>Precio y existencias reales.</strong></li>\n  <li><strong>Variantes</strong> cuando aplique: talla, color, presentación.</li>\n  <li><strong>Categorías</strong> pensadas como las buscaría un cliente, no como está organizada tu bodega.</li>\n</ul>\n<p>Empezá con tus veinte productos que más rotan. Es mejor una tienda con veinte productos bien presentados que una con trescientos a medias.</p>\n\n<h2>Paso 6: Definí los envíos con números</h2>\n<p>Esta es la parte donde más tiendas guatemaltecas improvisan. Necesitás decidir:</p>\n<ul>\n  <li>Cuánto cobrás dentro de la ciudad capital.</li>\n  <li>Cuánto cobrás al interior, y si vas a diferenciar por departamento o poner una tarifa única.</li>\n  <li>Si ofrecés envío gratis a partir de cierto monto, y si ese monto te deja margen.</li>\n  <li>Si permitís retiro en tienda o punto de encuentro.</li>\n  <li>En cuántos días entregás, y decilo en el sitio.</li>\n</ul>\n<p>Configurá esas reglas en la tienda para que el cliente vea el costo de envío <strong>antes</strong> de confirmar. Sorprender con el costo de envío al final es de las principales razones por las que se abandona un carrito.</p>\n\n<h2>Paso 7: Habilitá formas de pago que la gente use</h2>\n<p>En Guatemala, la combinación que mejor funciona al arrancar es esta:</p>\n<ul>\n  <li><strong>Depósito o transferencia bancaria</strong> con carga del comprobante. Es lo más usado y no tiene costo por transacción.</li>\n  <li><strong>Pago contra entrega</strong> en efectivo. Genera confianza en clientes que compran por primera vez, aunque implica riesgo de pedidos falsos.</li>\n  <li><strong>Tarjeta de crédito y débito</strong> mediante una pasarela. La opción más común es Visanet Epay, y requiere afiliación con un banco. Lo explicamos en <a href=\"/blog/como-cobrar-con-tarjeta-sitio-web-guatemala/\">cómo cobrar con tarjeta en tu sitio web</a>.</li>\n</ul>\n<p>Nuestra recomendación: arrancá con transferencia y contra entrega, medí cuántos pedidos entran al mes y activá la tarjeta cuando el volumen justifique la afiliación y su comisión.</p>\n\n<h2>Paso 8: Resolvé la facturación antes de vender</h2>\n<p>En Guatemala la facturación electrónica en línea (FEL) es obligatoria y se emite a través de un certificador autorizado por la SAT. El comprobante que genera la tienda cuando alguien compra <strong>no es una factura</strong>: es un recibo de pedido.</p>\n<p>Hay dos caminos. El manual, que funciona bien cuando tenés pocos pedidos: recibís el pedido y emitís la factura desde el sistema de tu certificador. Y el automatizado, que conecta la tienda con el certificador mediante una integración. Definí cuál vas a usar desde el inicio y qué datos fiscales le vas a pedir al cliente durante la compra, para no andar persiguiendo NIT después.</p>\n\n<h2>Paso 9: Probá, publicá y medí</h2>\n<p>Antes de anunciar la tienda, hacé al menos tres compras de prueba completas desde un celular: una con transferencia, una contra entrega y, si la activaste, una con tarjeta. Revisá que lleguen los correos de confirmación, que el costo de envío sea el correcto y que el pedido aparezca completo en el panel.</p>\n<p>Después de publicar, mirá dos números cada semana: cuánta gente llega a la tienda y cuántos completan la compra. Si entra mucha gente y nadie compra, el problema está en el precio, en el envío o en la confianza. Si no entra nadie, el problema es de difusión, no de la tienda.</p>\n\n<h2>Cuánto cuesta y cuánto tarda</h2>\n<p>Montar una tienda con nosotros cuesta Q1,750 al año e incluye dominio, alojamiento con SSL, la carga inicial del catálogo, la configuración de envíos y formas de pago, y la capacitación de tu equipo. El cobro con tarjeta agrega Q750 al año. El detalle está en <a href=\"/tiendas-virtuales-guatemala/\">tiendas virtuales</a>.</p>\n<p>En tiempo, lo normal son dos a tres semanas, y lo que manda el reloj es qué tan rápido llegue tu listado de productos con fotos. La tienda se arma rápido; el catálogo es lo que toma trabajo.</p>\n<p>Si querés que revisemos tu caso concreto —qué vendés, cuántos productos y cómo despachás— <a href=\"/contacto/\">escribinos</a> y te decimos si te conviene una tienda o un catálogo con cotización.</p>', '/assets/img/blog/crear-tienda-en-linea-guatemala.svg', 'Ilustración de los pasos para montar una tienda en línea', 2, 'Equipo de paginasweb.gt', '2026-02-11 09:00:00', '2026-02-11 09:00:00', 'Cómo Crear una Tienda en Línea en Guatemala | Guía', 'Guía paso a paso para montar tu tienda en línea en Guatemala: dominio, plataforma, catálogo, envíos, formas de pago locales y facturación FEL.', 1, 1),
  (3, 'cuanto-cuesta-una-pagina-web-en-guatemala', 'Cuánto cuesta una página web en Guatemala en 2026', 'De Q800 a Q30,000: por qué hay tanta diferencia entre cotizaciones y cómo saber cuál te conviene de verdad.', '<p>Si pediste tres cotizaciones para tu página web, seguramente te dieron tres números que no se parecen en nada: Q800, Q4,500 y Q18,000. Es la pregunta que más nos hacen y la que peor se contesta en internet, porque casi todos los artículos terminan diciendo \"depende\" sin explicar de qué.</p>\n<p>Vamos a explicarlo con números y con el detalle de qué estás comprando en cada rango. Los precios son de Guatemala, en quetzales, y reflejan lo que se ve en el mercado local en 2026.</p>\n\n<h2>La respuesta corta</h2>\n<p>Una página web informativa para una pequeña o mediana empresa en Guatemala cuesta entre <strong>Q1,000 y Q3,500 el primer año</strong>, incluyendo dominio y alojamiento. Una tienda en línea sencilla arranca alrededor de <strong>Q1,700 y llega a Q8,000</strong> según el catálogo y las formas de pago. Un desarrollo a la medida con integraciones a sistemas internos empieza en <strong>Q15,000</strong> y no tiene techo definido.</p>\n<p>Ahora, lo importante: dentro de un mismo rango puede haber diferencias enormes en lo que recibís. Eso es lo que vamos a desglosar.</p>\n\n<h2>Qué compone el precio de una página web</h2>\n<p>Toda cotización, sin importar quién la haga, cubre alguna combinación de estos seis costos. Cuando compares, revisá cuáles están incluidos y cuáles no:</p>\n<ol>\n  <li><strong>Dominio.</strong> El nombre de tu sitio. Un .com ronda entre US$12 y US$20 al año. Un .com.gt o un .gt se cotizan aparte y suelen costar más, porque los administra el registro nacional.</li>\n  <li><strong>Alojamiento (hosting).</strong> El espacio en el servidor. Un plan compartido decente en Guatemala o en el extranjero va de Q300 a Q1,200 al año. Los planes de menos de Q200 al año casi siempre son servidores saturados donde tu sitio va a cargar lento.</li>\n  <li><strong>Certificado SSL.</strong> El candado del navegador. Hoy hay opciones gratuitas y confiables, así que si te lo cobran como extra caro, preguntá por qué.</li>\n  <li><strong>Diseño y maquetación.</strong> Aquí está la mayor parte del costo y la mayor variación. No es lo mismo adaptar una plantilla comprada que diseñar la estructura desde las necesidades de tu negocio.</li>\n  <li><strong>Contenido.</strong> Redactar los textos, ordenar la información, preparar las fotografías. Este renglón es el que más se omite en las cotizaciones baratas, y el que más atrasa los proyectos cuando le queda al cliente.</li>\n  <li><strong>Soporte y mantenimiento.</strong> Actualizaciones, respaldos, cambios de contenido, atención cuando algo falla. Puede venir incluido en la anualidad o cobrarse por hora.</li>\n</ol>\n\n<h2>Los rangos, explicados</h2>\n\n<h3>Menos de Q1,000: la tarjeta de presentación</h3>\n<p>En este rango normalmente estás comprando una plantilla lista, con tus colores y tu logo puestos encima. Los textos los escribís vos. El soporte es informal, muchas veces por WhatsApp con un freelance que también tiene otro trabajo. No hay optimización de velocidad ni trabajo de SEO más allá de lo que trae la plantilla.</p>\n<p>¿Sirve? Para un negocio que apenas está arrancando y solo necesita un lugar a dónde mandar a la gente, sí. Es mejor eso que nada. El problema aparece cuando el negocio crece y hay que cambiar algo: si nadie documentó nada y el freelance ya no contesta, terminás rehaciendo el sitio.</p>\n\n<h3>Entre Q1,000 y Q3,500: el sitio de trabajo</h3>\n<p>Este es el rango donde entra la mayoría de las pequeñas y medianas empresas guatemaltecas, y donde ubicamos nuestro servicio de <a href=\"/diseno-de-paginas-web-guatemala/\">diseño de páginas web</a> a Q1,250 al año. Acá deberías recibir: estructura pensada para tu tipo de negocio, textos redactados por el proveedor, imágenes preparadas, versión móvil probada de verdad, correos con tu dominio, analítica configurada y soporte durante el año.</p>\n<p>La diferencia entre una cotización de Q1,200 y una de Q3,200 dentro de este rango suele estar en la cantidad de páginas, en si el proveedor escribe o no los textos, y en si te dan un panel para administrar el contenido vos mismo.</p>\n\n<h3>Entre Q3,500 y Q10,000: sitios con función</h3>\n<p>Acá caben tiendas en línea con catálogos grandes, sitios con sistema de reservas o citas, portales con área privada para clientes, o sitios corporativos con muchas secciones y contenido en dos idiomas. También entra el trabajo de fotografía profesional cuando el negocio lo amerita.</p>\n\n<h3>Más de Q10,000: desarrollo a la medida</h3>\n<p>Integraciones con sistemas de inventario o contabilidad, aplicaciones web con usuarios y permisos, plataformas con lógica propia. Si te cotizan esto para un sitio de cinco páginas, pedí que te expliquen qué justifica el monto.</p>\n\n<h2>El costo que casi nadie te menciona</h2>\n<p>El precio de la renovación. Muchas cotizaciones enseñan un número atractivo el primer año y no dicen qué pasa el segundo. Después llega un cobro de renovación que duplica lo que pagaste, o peor: el proveedor desaparece y el dominio queda registrado a su nombre.</p>\n<p>Preguntá siempre tres cosas por escrito: cuánto cuesta la renovación anual, qué incluye, y a nombre de quién queda registrado el dominio. Si la respuesta a la última pregunta no es \"a nombre de tu empresa\", tenés un problema esperándote.</p>\n\n<h2>Las seis preguntas que debés hacer antes de aceptar</h2>\n<p>Estas preguntas explican casi toda la diferencia entre dos cotizaciones que se ven parecidas:</p>\n<ul>\n  <li><strong>¿A nombre de quién queda el dominio?</strong> Debe quedar a nombre de tu empresa, siempre.</li>\n  <li><strong>¿El precio incluye el alojamiento del primer año?</strong> Y cuánto cuesta a partir del segundo.</li>\n  <li><strong>¿Quién escribe los textos?</strong> Si te toca a vos, sumale el tiempo que vas a invertir o el costo de un redactor.</li>\n  <li><strong>¿Cuántas rondas de revisión entran?</strong> Y qué pasa si querés un cambio después de publicar.</li>\n  <li><strong>¿Me entregan los accesos si me quiero cambiar de proveedor?</strong> La respuesta correcta es sí, sin condiciones raras.</li>\n  <li><strong>¿Qué incluye el soporte?</strong> Cambiar un precio o una foto no debería costar extra.</li>\n</ul>\n\n<h2>Señales de que un precio es demasiado bueno</h2>\n<p>Cuando el número es muy bajo, el costo aparece en otro lado. Estas son las señales que hemos visto repetirse en los sitios que nos toca rescatar:</p>\n<ul>\n  <li>El sitio no tiene panel de administración y cada cambio hay que pedirlo.</li>\n  <li>El dominio está registrado a nombre de la agencia o del diseñador.</li>\n  <li>El alojamiento es una carpeta dentro del servidor de otro cliente.</li>\n  <li>Los textos son genéricos y podrían servir para cualquier negocio del mismo rubro.</li>\n  <li>Prometen \"primer lugar en Google\" como parte del paquete.</li>\n  <li>Las fotos son de banco de imágenes y aparecen en otros sitios guatemaltecos.</li>\n</ul>\n\n<h2>Cómo decidir sin volverse loco</h2>\n<p>Definí primero qué querés que haga el sitio. No \"verse bien\": qué acción concreta querés que tome la persona que entra. ¿Que te escriba por WhatsApp? ¿Que llene un formulario con los datos de su proyecto? ¿Que compre? ¿Que descargue tu catálogo? Con esa respuesta clara, la cotización correcta se vuelve evidente, porque podés preguntarle a cada proveedor cómo va a lograr específicamente eso.</p>\n<p>Después revisá trabajos anteriores, pero no las capturas de la presentación: pedí direcciones y abrilas en tu celular. Fijate cuánto tardan en cargar, si los textos dicen algo o son relleno, y si encontrarías el número de teléfono en menos de tres segundos.</p>\n<p>Y por último, considerá el costo de no hacerlo. Si tu negocio factura Q50,000 al mes y perdés dos cotizaciones al mes por no tener dónde mandar a la gente, la discusión entre Q1,250 y Q2,500 anuales deja de ser lo importante.</p>\n\n<p>Si querés ver exactamente qué incluye cada uno de nuestros servicios y cómo se paga, está todo en la página de <a href=\"/precios/\">precios</a>. Y si tenés una cotización de otro proveedor y querés una segunda opinión sobre si es razonable, <a href=\"/contacto/\">escribinos</a>: la revisamos sin compromiso.</p>', '/assets/img/blog/precios-pagina-web-guatemala.svg', 'Ilustración de una calculadora y un sitio web con precios en quetzales', 1, 'Equipo de paginasweb.gt', '2026-01-14 09:00:00', '2026-01-14 09:00:00', 'Cuánto Cuesta una Página Web en Guatemala 2026', 'Rangos reales de precios en Guatemala, qué explica cada salto de precio y las seis preguntas que debés hacer antes de aceptar una cotización.', 1, 1),
  (4, 'dominio-gt-como-registrarlo', 'Qué es un dominio .gt y cómo registrarlo', 'Diferencias entre .gt y .com.gt, quién administra el registro, requisitos y si de verdad ayuda a posicionar en el buscador.', '<p>Cada país tiene su extensión de dominio. La de Guatemala es <strong>.gt</strong>, y a diferencia de un .com, que cualquiera registra en dos minutos con tarjeta, el .gt tiene sus propias reglas, su propio administrador y algunas particularidades que conviene entender antes de decidir.</p>\n\n<h2>Qué es exactamente</h2>\n<p>El .gt es el dominio de nivel superior de código de país asignado a Guatemala. Su administración corresponde al registro nacional de dominios, una función que en Guatemala ha estado a cargo del ámbito académico, concretamente de la Universidad del Valle de Guatemala, siguiendo el modelo de varios países de la región.</p>\n<p>Esto tiene una consecuencia práctica: el .gt no se registra en cualquier proveedor internacional de dominios. Se gestiona a través del registro nacional o de proveedores que operan con él, y el proceso, los precios y los requisitos los define ese registro, no el mercado internacional.</p>\n\n<h2>.gt o .com.gt: cuál te toca</h2>\n<p>Históricamente, Guatemala usaba una estructura de segundo nivel, igual que muchos países:</p>\n<ul>\n  <li><strong>.com.gt</strong> para empresas y actividades comerciales.</li>\n  <li><strong>.net.gt</strong> para proveedores de servicios de red.</li>\n  <li><strong>.org.gt</strong> para organizaciones sin fines de lucro.</li>\n  <li><strong>.edu.gt</strong> para instituciones educativas.</li>\n  <li><strong>.gob.gt</strong> para entidades del Estado.</li>\n  <li><strong>.mil.gt</strong> para el ámbito militar.</li>\n  <li><strong>.ind.gt</strong> para personas individuales.</li>\n</ul>\n<p>Con el tiempo se habilitó también el registro directo bajo <strong>.gt</strong>, sin el segundo nivel. Eso permite nombres más cortos y memorables: en lugar de <code>tuempresa.com.gt</code>, simplemente <code>tuempresa.gt</code>. Este mismo sitio usa esa forma.</p>\n<p>¿Cuál conviene? Si el nombre corto está libre, el .gt directo se dicta más fácil por teléfono, se escribe más rápido y se ve más moderno. Si ya no está disponible o tu empresa lleva años usando su .com.gt, no hay razón para cambiarlo: en términos de posicionamiento las dos formas funcionan igual.</p>\n\n<h2>Qué se necesita para registrarlo</h2>\n<p>El registro de un dominio .gt normalmente implica:</p>\n<ul>\n  <li><strong>Datos del titular.</strong> Nombre de la empresa o de la persona, con dirección y contacto. El titular es quien tiene el control del dominio, así que este dato importa más de lo que parece.</li>\n  <li><strong>Contacto administrativo y técnico.</strong> Puede ser tu proveedor web, pero el titular seguís siendo vos.</li>\n  <li><strong>Servidores de nombres (DNS).</strong> A dónde apunta el dominio. Los da tu alojamiento.</li>\n  <li><strong>Pago del período.</strong> El registro es por períodos anuales renovables.</li>\n</ul>\n<p>Los precios los publica el registro nacional y suelen expresarse en dólares. Son más altos que un .com genérico —eso es normal en los dominios de país de la región— y cambian cada cierto tiempo, así que conviene confirmar la tarifa vigente al momento de registrar en lugar de fiarse de una cifra vieja de internet.</p>\n\n<h2>El punto crítico: a nombre de quién queda</h2>\n<p>Es la advertencia más importante de este artículo. El dominio debe quedar registrado a nombre de <strong>tu empresa</strong>, no del proveedor que te hace la página.</p>\n<p>Nos ha tocado ayudar a negocios que llevaban años pagando renovaciones y descubrieron, al querer cambiar de proveedor, que el dominio nunca estuvo a su nombre. Recuperarlo cuando el proveedor no coopera es lento y a veces imposible. El dominio es el activo digital más importante de tu negocio: es la dirección donde vive tu reputación, tus enlaces y tus correos.</p>\n<p>Preguntá siempre, por escrito, quién figura como titular. Y guardá una copia del comprobante de registro.</p>\n\n<h2>¿Un dominio .gt ayuda a posicionar en Google Guatemala?</h2>\n<p>Un poco, y menos de lo que la gente cree.</p>\n<p>Google usa la extensión de país como una de varias señales para entender a qué mercado se dirige un sitio. Un .gt indica con claridad que tu contenido es para Guatemala. Es una señal útil, sobre todo para un negocio local.</p>\n<p>Pero es una señal entre muchas, y no la más fuerte. Un .com bien trabajado, con contenido claramente guatemalteco, precios en quetzales, dirección local y buen desempeño técnico, va a rendir mejor que un .gt con contenido genérico. Nunca hemos visto un sitio subir posiciones solo por cambiar de extensión.</p>\n<p>Hay además un costo a considerar: si tu negocio también vende fuera de Guatemala, un .gt le dice a Google y a los usuarios que sos exclusivamente local. Para un exportador o para quien atiende clientes en toda Centroamérica, un .com suele ser mejor decisión.</p>\n\n<h2>Cómo elegir el nombre</h2>\n<p>Reglas simples que evitan arrepentimientos:</p>\n<ul>\n  <li><strong>Corto.</strong> Si no cabe cómodo en una tarjeta de presentación, es largo.</li>\n  <li><strong>Fácil de dictar.</strong> Probalo: decilo en voz alta por teléfono y fijate si la otra persona lo escribe bien a la primera.</li>\n  <li><strong>Sin guiones ni números.</strong> Se pierden al dictarlos y se ven improvisados.</li>\n  <li><strong>Sin faltas de ortografía intencionales</strong> para que \"quede libre\". El cliente va a escribir la palabra correcta.</li>\n  <li><strong>Que no dependa de una moda</strong> ni de un producto puntual que quizás dejés de vender.</li>\n  <li><strong>Revisá que la marca no esté registrada</strong> por alguien más antes de invertir en rótulos y papelería.</li>\n</ul>\n\n<h2>Después de registrarlo</h2>\n<p>Un dominio registrado no hace nada por sí solo. Falta:</p>\n<ol>\n  <li><strong>Apuntarlo a tu alojamiento</strong> configurando los servidores de nombres. El cambio puede tardar algunas horas en propagarse.</li>\n  <li><strong>Activar el certificado SSL</strong> para que el sitio abra con el candado. Hoy es un requisito, no un lujo.</li>\n  <li><strong>Configurar los registros de correo</strong> si vas a usar cuentas con tu dominio, incluidos SPF y DKIM para que tus mensajes no caigan en spam. Lo tratamos en <a href=\"/cuentas-de-correo-corporativo/\">correo corporativo</a>.</li>\n  <li><strong>Anotar la fecha de renovación</strong> en el calendario de la empresa, no solo en el correo de una persona. Los dominios que se pierden casi siempre se pierden por un aviso de renovación que llegó a la cuenta de alguien que ya no trabaja ahí.</li>\n</ol>\n\n<h2>Errores frecuentes con dominios en Guatemala</h2>\n<p>Estos son los que más nos ha tocado corregir:</p>\n<ul>\n  <li><strong>Registrar el dominio con el correo personal de un empleado.</strong> Cuando esa persona se va, los avisos de renovación se van con ella. Usá una cuenta de la empresa a la que tengan acceso al menos dos personas.</li>\n  <li><strong>Dejar vencer el dominio y creer que se recupera fácil.</strong> Después del vencimiento hay períodos de gracia y de redención con costos mayores, y al final el nombre puede liberarse para que cualquiera lo tome.</li>\n  <li><strong>Comprar varios dominios parecidos y publicar el mismo sitio en todos.</strong> Es una forma rápida de generar contenido duplicado. Si querés proteger variantes del nombre, registralas pero redirigilas todas al dominio principal.</li>\n  <li><strong>Cambiar de dominio sin redirecciones.</strong> Si tu sitio ya tenía años, cambiar de dirección sin configurar redirecciones permanentes borra de un día para otro el posicionamiento acumulado.</li>\n  <li><strong>Suponer que el dominio incluye el correo.</strong> Son servicios distintos. El dominio es la dirección; el correo hay que habilitarlo aparte.</li>\n</ul>\n\n<h2>¿Y si mi nombre ya está tomado?</h2>\n<p>Pasa seguido. Las opciones razonables son agregar una palabra que describa tu actividad o tu ciudad, usar la variante con o sin el segundo nivel, o considerar otra extensión. Lo que no recomendamos es forzar un nombre confuso solo por conservar la extensión: es mejor un .com claro que un .gt que nadie escribe bien.</p>\n<p>Si vas a contratar tu sitio con nosotros, el registro y la configuración del dominio van incluidos en el primer año, y queda a nombre de tu empresa. Podés ver el detalle en <a href=\"/precios/\">precios</a> o <a href=\"/contacto/\">escribirnos</a> para revisar qué nombres están disponibles para tu negocio.</p>', '/assets/img/blog/dominio-gt-guatemala.svg', 'Ilustración de un dominio con extensión punto gt', 4, 'Equipo de paginasweb.gt', '2026-05-13 09:00:00', '2026-05-13 09:00:00', 'Qué es un Dominio .gt y Cómo Registrarlo | Guatemala', 'Cómo funciona el dominio .gt de Guatemala, diferencias con .com.gt, quién lo administra, qué se necesita para registrarlo y cuándo conviene usarlo.', 1, 1),
  (5, 'errores-al-contratar-diseno-web-guatemala', '7 errores al contratar diseño web en Guatemala', 'Lo que revisamos cuando nos toca rescatar un sitio mal hecho, convertido en lista de verificación antes de firmar.', '<p>Una parte del trabajo que hacemos consiste en rescatar sitios: negocios que ya pagaron una página, no quedaron conformes y no saben cómo salir. Después de varios años de eso, los problemas se repiten con una regularidad sorprendente.</p>\n<p>Esta es la lista, en orden de qué tan caro sale cada error.</p>\n\n<h2>1. Dejar el dominio a nombre del proveedor</h2>\n<p>Es el más grave y el más común. El negocio contrata, paga cada año sin revisar nada y un día decide cambiar de proveedor. Ahí descubre que el dominio —su dirección en internet, donde llegan sus correos y donde apuntan todos los enlaces que ha ganado en años— está registrado a nombre de la agencia.</p>\n<p>Cuando el proveedor coopera, el traslado toma días. Cuando no, o cuando simplemente desapareció, la recuperación es lenta y a veces no se logra. Hemos visto negocios cambiar de nombre comercial por no poder recuperar su dominio.</p>\n<p><strong>Qué hacer:</strong> antes de pagar, preguntá por escrito quién queda como titular. La respuesta correcta es el nombre de tu empresa. Pedí el comprobante de registro y guardalo.</p>\n\n<h2>2. Quedar sin forma de editar tu propio contenido</h2>\n<p>El sitio se ve bien el día que se publica. Seis meses después cambiaste un precio, agregaste un servicio o cambiaste de número de teléfono, y para actualizar tenés que escribirle al diseñador, esperar y a veces pagar.</p>\n<p>El resultado predecible: el sitio se desactualiza. Precios viejos, un servicio que ya no ofrecés, un teléfono que ya no existe. Un sitio desactualizado hace más daño que no tener sitio, porque el cliente asume que el negocio ya no opera.</p>\n<p><strong>Qué hacer:</strong> pedí que te muestren el panel de administración <em>antes</em> de contratar. No una promesa: una demostración de cómo se cambia un texto y una foto. Y confirmá que la capacitación esté incluida.</p>\n\n<h2>3. Creerle a quien promete el primer lugar en Google</h2>\n<p>Nadie puede garantizar una posición en Google. Ni nosotros, ni la agencia más grande de la región, porque el resultado depende de los algoritmos del buscador, de tu competencia y del tiempo. Google mismo lo dice en su documentación pública.</p>\n<p>Peor todavía: algunos de los que prometen resultados rápidos usan tácticas que hoy generan penalizaciones. Llenar el pie de página con nombres de municipios, crear una página casi idéntica por cada palabra clave, esconder texto del mismo color que el fondo, comprar paquetes de enlaces. Todo eso funcionó hace más de una década. Hoy es la forma más rápida de que Google deje de mostrar tu sitio.</p>\n<p><strong>Qué hacer:</strong> desconfiá de garantías de posición. Lo que sí se puede comprometer es el trabajo: velocidad de carga, estructura correcta, títulos y descripciones únicos, datos estructurados, contenido útil y un plan de publicación. Pedí que te expliquen qué van a hacer, no qué posición te prometen.</p>\n\n<h2>4. Aceptar textos genéricos</h2>\n<p>\"Somos una empresa líder comprometida con la excelencia y la satisfacción de nuestros clientes.\" Ese párrafo aparece, con variaciones mínimas, en cientos de sitios guatemaltecos. No dice nada, no diferencia y no ayuda a que te encuentren.</p>\n<p>El problema de fondo es que muchos proveedores no incluyen la redacción en el precio, se la dejan al cliente, el cliente no tiene tiempo y termina copiando de algún lado. Así nacen los sitios que se parecen entre sí.</p>\n<p><strong>Qué hacer:</strong> definí desde la cotización quién escribe. Si te toca a vos, sumá ese tiempo al costo real del proyecto. Si lo escribe el proveedor, pedí ver un ejemplo de textos que haya escrito para otro cliente.</p>\n\n<h2>5. No revisar el sitio en un celular</h2>\n<p>Casi todos los proveedores dicen que el sitio es \"responsive\". Muy pocos lo prueban de verdad. La diferencia entre que se vea y que se use es enorme: botones demasiado juntos para el dedo, textos de nueve píxeles, tablas que obligan a hacer zoom, formularios donde el teclado tapa el campo que estás llenando, imágenes pesadas que tardan ocho segundos con datos móviles.</p>\n<p>Y en Guatemala esto pesa muchísimo: la mayoría de tus visitas van a llegar desde un teléfono, muchas veces con señal irregular.</p>\n<p><strong>Qué hacer:</strong> abrí en tu propio celular tres sitios que el proveedor haya hecho. Cronometrá cuánto tardan en cargar con datos móviles, no con wifi. Intentá encontrar el número de teléfono en menos de tres segundos. Si eso falla, lo demás no importa.</p>\n\n<h2>6. Comparar precios sin comparar alcances</h2>\n<p>Tres cotizaciones: Q900, Q1,800 y Q6,000. La reacción natural es pensar que la de Q6,000 está inflada. Puede ser, pero también puede ser la única que incluye redacción, fotografía, cinco secciones más y un año de soporte.</p>\n<p>El precio sin alcance no dice nada. Y el error más caro no es pagar de más: es pagar poco por algo que después hay que rehacer completo.</p>\n<p><strong>Qué hacer:</strong> pedile a cada proveedor que responda lo mismo por escrito: cuántas páginas, quién escribe los textos, cuántas revisiones entran, qué incluye la renovación anual, qué cuesta extra y qué pasa si te querés cambiar. Con esas respuestas al lado, las cotizaciones se vuelven comparables. Nosotros publicamos todo eso abiertamente en <a href=\"/precios/\">precios</a>, y escribimos aparte sobre <a href=\"/blog/cuanto-cuesta-una-pagina-web-en-guatemala/\">cuánto cuesta realmente una página web en Guatemala</a>.</p>\n\n<h2>7. No preguntar qué pasa el segundo año</h2>\n<p>La cotización cubre el primer año. ¿Y después? Este es el punto donde aparecen las sorpresas: renovaciones que duplican el precio inicial, cobros por cambios que antes eran gratis, o simplemente un proveedor que dejó de contestar y el sitio se cayó cuando venció el alojamiento.</p>\n<p><strong>Qué hacer:</strong> pedí el precio de renovación por escrito desde el inicio, junto con qué incluye. Y preguntá directamente: \"si algún día quiero irme, ¿me entregan los archivos y los accesos?\". La respuesta correcta es sí, sin condiciones.</p>\n\n<h2>Una señal que vale por todas</h2>\n<p>Hay una pregunta que resume las nueve anteriores y que casi nadie hace: <em>\"¿qué pasa si no quedo conforme?\"</em>. La respuesta te dice más del proveedor que su portafolio.</p>\n<p>Un proveedor serio te explica cómo funciona el proceso de revisiones, qué pasa si el diseño no te convence en la primera propuesta y hasta dónde llega el acompañamiento. Uno que improvisa se incomoda con la pregunta, cambia de tema o promete que \"eso nunca pasa\". Los proyectos que terminan mal casi siempre empiezan con esa evasiva.</p>\n<p>Y si el proveedor te dice de entrada que tu proyecto no le encaja, o que lo que necesitás es otra cosa, tomalo como buena señal. Nosotros preferimos decir que no a un proyecto antes que aceptarlo y quedar mal; es más barato para los dos.</p>\n\n<h2>Lista de verificación antes de firmar</h2>\n<p>Si solo te llevás una cosa de este artículo, que sea esta lista. Antes de pagar, confirmá por escrito:</p>\n<ul>\n  <li>El dominio queda a nombre de mi empresa.</li>\n  <li>Recibo acceso a un panel para editar contenido, con capacitación.</li>\n  <li>Sé exactamente qué incluye el precio y qué se cobra aparte.</li>\n  <li>Sé cuánto cuesta la renovación anual y qué cubre.</li>\n  <li>Sé quién escribe los textos.</li>\n  <li>Sé cuántas revisiones entran en el proceso.</li>\n  <li>Si me quiero cambiar de proveedor, me entregan archivos y accesos.</li>\n  <li>Vi al menos tres sitios anteriores abiertos en mi propio celular.</li>\n  <li>Nadie me prometió una posición garantizada en Google.</li>\n</ul>\n<p>Nueve puntos. Toma diez minutos preguntarlos y evita la mayoría de los problemas que nos toca resolver.</p>\n<p>Si tenés una cotización sobre la mesa y querés una segunda opinión, <a href=\"/contacto/\">escribinos</a>. La revisamos sin compromiso, aunque termines contratando con otro.</p>', '/assets/img/blog/errores-contratar-diseno-web.svg', 'Ilustración de una lista de verificación antes de contratar diseño web', 5, 'Equipo de paginasweb.gt', '2026-06-10 09:00:00', '2026-06-10 09:00:00', '7 Errores al Contratar Diseño Web en Guatemala', 'Los errores que salen caros al contratar una página web en Guatemala: dominio a nombre ajeno, sin panel, promesas de SEO y contratos sin salida.', 1, 1),
  (6, 'woocommerce-vs-shopify-guatemala', 'WooCommerce o Shopify para un negocio en Guatemala', 'Costos a tres años, compatibilidad con pasarelas guatemaltecas y el criterio que de verdad debería decidir tu elección.', '<p>Es la pregunta que aparece apenas alguien decide vender en línea. Y la mayoría de comparaciones que se encuentran están escritas por afiliados que cobran comisión por recomendar una de las dos, así que conviene aclarar de entrada nuestra posición: nosotros montamos tiendas en WooCommerce. Aun así, vamos a explicar en qué casos Shopify es la mejor decisión, porque los hay.</p>\n\n<h2>La diferencia de fondo</h2>\n<p><strong>WooCommerce</strong> es un complemento gratuito de WordPress. Lo instalás en tu propio alojamiento, con tu propio dominio, y el código es tuyo. Nadie te puede subir la renta ni cerrarte la tienda.</p>\n<p><strong>Shopify</strong> es un servicio por suscripción. Pagás una mensualidad y ellos se encargan de todo lo técnico: servidores, actualizaciones, seguridad. A cambio, jugás con sus reglas y dentro de sus límites.</p>\n<p>Es la diferencia entre comprar un local y alquilarlo. Ninguna de las dos es incorrecta; dependen de cuánto querés involucrarte.</p>\n\n<h2>Costos reales para una tienda guatemalteca</h2>\n<p>Comparemos una tienda pequeña con unos cincuenta productos, a tres años.</p>\n\n<h3>WooCommerce</h3>\n<ul>\n  <li>Dominio: entre US$12 y US$20 al año.</li>\n  <li>Alojamiento adecuado para una tienda: entre Q600 y Q1,500 al año.</li>\n  <li>Plantilla o desarrollo del diseño: pago único, o incluido si contratás el servicio armado.</li>\n  <li>Complementos de pago o envío: algunos gratuitos, otros con licencia anual.</li>\n  <li>Comisión por venta de la plataforma: <strong>ninguna</strong>.</li>\n</ul>\n<p>Con nuestro servicio, esto queda en Q1,750 el primer año con todo incluido, y la renovación mantiene el mismo esquema. A tres años, alrededor de Q5,250 sin comisiones por venta.</p>\n\n<h3>Shopify</h3>\n<ul>\n  <li>Plan básico: alrededor de US$29 al mes según el plan y el momento, es decir, unos US$348 al año.</li>\n  <li>Dominio: similar, entre US$12 y US$20.</li>\n  <li>Aplicaciones del marketplace: muchas cobran mensualidad propia, entre US$5 y US$30 cada una.</li>\n  <li>Comisión adicional por transacción si <strong>no</strong> usás su pasarela propia. Y Shopify Payments no está disponible en Guatemala.</li>\n</ul>\n<p>A tres años, contando solo el plan y el dominio, andás arriba de US$1,100, que al tipo de cambio son más de Q8,500. Con dos o tres aplicaciones de pago, sube bastante más.</p>\n<p>Ojo con un detalle importante: los precios de Shopify están en dólares y se ajustan. Tu costo sube si el tipo de cambio se mueve, aunque tus ventas sigan en quetzales.</p>\n\n<h2>El punto que decide la mayoría de casos en Guatemala: las pasarelas de pago</h2>\n<p>Acá está la razón práctica por la que la mayoría de tiendas guatemaltecas terminan en WooCommerce.</p>\n<p>Shopify Payments, su sistema propio de cobro con tarjeta, no opera en Guatemala. Eso significa que tenés que usar una pasarela externa y, además, Shopify cobra una comisión adicional por cada transacción que no pase por su sistema. Y la integración con las pasarelas locales guatemaltecas, empezando por Visanet Epay, no es algo que exista listo en su tienda de aplicaciones: hay que resolverlo con desarrollo a la medida, cuando se puede.</p>\n<p>En WooCommerce, en cambio, la integración de una pasarela local es un trabajo conocido: se conecta el módulo, se hacen pruebas y queda funcionando. Lo mismo aplica para pagos con depósito y carga de comprobante, o para contra entrega con reglas por departamento, que son formas de pago muy guatemaltecas y que en Shopify hay que forzar.</p>\n\n<h2>Facturación electrónica FEL</h2>\n<p>Otro punto local. En Guatemala la factura electrónica se emite a través de un certificador autorizado por la SAT. Como WooCommerce corre en tu propio servidor y su código es abierto, conectar el flujo de pedidos con un certificador es un desarrollo perfectamente viable.</p>\n<p>Con Shopify dependés de que exista una aplicación que haga esa conexión o de usar su interfaz de programación, lo que en la práctica significa contratar a alguien que lo desarrolle y mantenerlo funcionando cuando la plataforma cambie.</p>\n\n<h2>Facilidad de uso</h2>\n<p>Acá Shopify gana sin discusión. Su panel es más limpio, la curva de aprendizaje es corta y el soporte contesta las 24 horas en inglés y en español. Si nunca has administrado un sitio y vas a manejarlo vos solo, la vas a pasar mejor.</p>\n<p>WooCommerce tiene más opciones y por eso más lugares donde perderse. Ahora bien, esto se resuelve con capacitación: cuando entregamos una tienda, damos una sesión por videollamada y dejamos el panel ordenado para que el equipo haga lo que necesita sin tocar lo demás.</p>\n\n<h2>Mantenimiento</h2>\n<p>Shopify se actualiza solo. Es una ventaja real y hay que reconocerla.</p>\n<p>WooCommerce requiere mantenimiento: actualizar WordPress, los complementos y revisar que nada se rompa. Si nadie lo hace, la tienda se vuelve vulnerable. Por eso nuestro servicio incluye ese mantenimiento durante el año; si vas por tu cuenta, tenés que contemplarlo.</p>\n\n<h2>Propiedad y salida</h2>\n<p>Con WooCommerce, la tienda es tuya: base de datos, archivos, dominio. La podés mover a otro servidor cuando quieras.</p>\n<p>Con Shopify, podés exportar tu lista de productos y de clientes, pero el diseño, la configuración y el historial se quedan. Migrar de Shopify a otra plataforma es rehacer buena parte del trabajo. Es un costo que no se ve al principio pero existe.</p>\n\n<h2>Entonces, ¿cuál elegir?</h2>\n<p><strong>Elegí Shopify si:</strong> vendés principalmente al extranjero y vas a cobrar con pasarelas internacionales; no tenés a nadie que se ocupe de mantenimiento y preferís pagar por no pensar; necesitás lanzar en cuestión de días; o tu catálogo cambia constantemente y valorás mucho la comodidad del panel.</p>\n<p><strong>Elegí WooCommerce si:</strong> vendés en Guatemala y necesitás cobrar con tarjeta mediante una pasarela local; querés depósito, transferencia con comprobante o contra entrega con reglas propias; vas a necesitar conectar la facturación FEL; te importa que la tienda sea un activo tuyo; o querés evitar un costo mensual en dólares.</p>\n<p>Para la mayoría de negocios guatemaltecos que venden dentro del país, la segunda lista pesa más. Esa es la razón por la que trabajamos con WooCommerce, no una preferencia técnica.</p>\n\n<h2>SEO: ¿alguna posiciona mejor?</h2>\n<p>Las dos pueden posicionar bien, y quien diga lo contrario está vendiendo algo. Lo que cambia es cuánto control tenés.</p>\n<p>Shopify impone una estructura fija de direcciones: los productos siempre viven bajo <code>/products/</code> y las categorías bajo <code>/collections/</code>. No es un problema grave, pero no lo podés cambiar, y en tiendas con muchas variantes se generan direcciones duplicadas que hay que controlar con etiquetas canónicas.</p>\n<p>WooCommerce te deja definir la estructura de direcciones, editar cada etiqueta de título y descripción, controlar los datos estructurados de producto y trabajar el contenido con la libertad de WordPress, que sigue siendo la mejor herramienta para publicar guías y artículos alrededor de lo que vendés. Esa parte importa: en Guatemala, buena parte del tráfico de una tienda pequeña no llega buscando la marca, sino buscando el problema que el producto resuelve.</p>\n<p>La velocidad depende más del alojamiento y de las imágenes que de la plataforma. Una tienda WooCommerce en un servidor barato y con fotos de cuatro megas va a ser lenta; la misma tienda bien optimizada carga igual de rápido que cualquier Shopify.</p>\n\n<h2>Una tercera opción que casi nadie menciona</h2>\n<p>Si todavía no estás seguro de que vas a vender lo suficiente, no montés ninguna de las dos todavía. Armá un catálogo en línea sin carrito, con precios visibles y un botón de WhatsApp por producto. Cuesta menos, se hace más rápido y te dice en dos meses si hay demanda real. Cuando la haya, montás la tienda con datos en la mano en lugar de con una corazonada.</p>\n<p>Si querés que revisemos tu caso —qué vendés, a quién y cómo cobrás hoy— <a href=\"/contacto/\">escribinos</a>. Y si ya decidiste, en <a href=\"/tiendas-virtuales-guatemala/\">tiendas virtuales</a> está el detalle de lo que incluye nuestro servicio.</p>', '/assets/img/blog/woocommerce-vs-shopify-guatemala.svg', 'Comparación entre dos plataformas de comercio electrónico', 2, 'Equipo de paginasweb.gt', '2026-03-10 09:00:00', '2026-03-10 09:00:00', 'WooCommerce vs Shopify en Guatemala | Comparación', 'WooCommerce y Shopify comparados para vender en Guatemala: costos en quetzales, pasarelas locales, facturación FEL y a quién le sirve cada una.', 1, 1);
